local config = {
  ui_story_5061_50610101_1_dialog_content = "Registro de Investigación, Entrada 154.",
  ui_story_5061_50610101_2_dialog_content = "27 de septiembre, 22:00. Está nevando.",
  ui_story_5061_50610101_3_dialog_content = "Después de viajar a los rincones más lejanos de Northland, actualmente me estoy acercando al sitio de la <color=#FFB400>tormenta de aurora</color> de hace un siglo.",
  ui_story_5061_50610101_4_dialog_content = "Este fue un raro evento anómalo relacionado con la Aurora registrado en la historia de Northland, y la leyenda del Espíritu de la Aurora ha perdurado durante mucho tiempo desde entonces.",
  ui_story_5061_50610101_5_dialog_content = "Los Aurorianos nacen dependiendo de Lumina, y la Aurora solo aparece cuando la Lumina compacta cumple ciertas condiciones en un entorno específico.",
  ui_story_5061_50610101_6_dialog_content = "Es una manifestación extrema de energía pura... ¡quizás la forma más pura de Lumina!",
  ui_story_5061_50610101_7_dialog_content = "Llama a todos los Aurorianos como un faro en la noche, sirviendo como símbolo de su existencia.",
  ui_story_5061_50610101_8_dialog_content = "Naturalmente, un fenómeno tan raro como este está destinado a atraer la admiración y curiosidad de la gente... ¡Y yo no soy diferente!",
  ui_story_5061_50610101_9_dialog_content = "Existen muchas teorías sobre el origen de la Aurora. La teoría de la Turbulencia de la Zona Oscura, la teoría de la Luz Sagrada, la teoría de la Fragmentación Polar, la teoría de la Tormenta Electromagnética...",
  ui_story_5061_50610101_10_dialog_content = "Pero personalmente, creo que la teoría más plausible es la de la Fuente de Energía Antigua.",
  ui_story_5061_50610101_11_dialog_content = "La Aurora posee una cantidad inconcebible de poder, probablemente aprovechado por las antiguas civilizaciones ocultas justo debajo de nuestros pies.",
  ui_story_5061_50610101_12_dialog_content = "Los textos de Lumopolis indican que la primera Aurora surgió de un conjunto de ruinas antiguas. Sin embargo, las ruinas específicas en sí mismas son objeto de amplio debate.",
  ui_story_5061_50610101_13_dialog_content = "Si esta hipótesis es correcta, ¿encontraré el verdadero origen de la Aurora al final de mi excursión?",
  ui_story_5061_50610101_14_dialog_content = "...",
  ui_story_5061_50610101_15_dialog_content = "Son las 22:14. Creo que ahora estoy más allá de las fronteras de Northland, así como del alcance protector del Faro.",
  ui_story_5061_50610101_16_dialog_content = "Veo varias figuras oscuras de pie en las llanuras congeladas. Tal vez los restos de árboles antiguos, o posiblemente...",
  ui_story_5061_50610101_17_dialog_content = "...",
  ui_story_5061_50610101_18_dialog_content = "Para evitar la detección de Eclipsites, ahora apagaré el dispositivo de grabación.",
  ui_story_5061_50610101_19_dialog_content = "Si alguien descubre esta grabación, significa que mi suerte empeoró. Si eso sucede, por favor entregue esto a la Corte de Northland.",
  ui_story_5061_50610101_20_dialog_content = "Espero sinceramente que las futuras generaciones encuentren útil mi investigación para descubrir el origen de la Aurora.",
  ui_story_5061_50610101_21_dialog_content = "Para que algún día, finalmente podamos entender...",
  ui_story_5061_50610101_22_dialog_content = "De dónde vienen los Aurorianos y en qué tipo de mundo vivimos.",
  ui_story_5061_50610101_23_dialog_content = "... ¡Ay! ¿Es eso—?!",
  ui_story_5061_50610101_24_dialog_content = "En el hielo, ¿es eso... una persona?!",
  ui_story_5061_50610101_25_dialog_content = "... ¿Un viajero varado? O tal vez... ¿Podría ser este el legendario Espíritu de la Aurora?",
  ui_story_5061_50610101_26_dialog_content = "... ¿Sigue viva?",
  ui_story_5061_50610201_1_dialog_content = "(Jadeando) ¡Finalmente lo logré!",
  ui_story_5061_50610201_2_dialog_content = "¡La nieve se pone cada vez más pesada! ¡Tengo que volver al interior del Coloso!",
  ui_story_5061_50610201_3_dialog_content = "Simplemente frota tus manos juntas y respira sobre ellas...",
  ui_story_5061_50610201_4_dialog_content = "Haaah—Haaaaah—",
  ui_story_5061_50610201_5_dialog_content = "¡No sirve! Incluso cuando hago eso, ¡mis manos siguen congeladas!",
  ui_story_5061_50610201_6_dialog_content = "Jaja, bueno, después de todo, ESTÁS en Northland...",
  ui_story_5061_50610201_7_dialog_content = "Si hubiera sabido que iba a hacer tanto frío, ¡habría traído más equipo de supervivencia invernal para el trabajo!",
  ui_story_5061_50610201_8_dialog_content = "En efecto, si Carleen estuviera cerca, definitivamente te lo habría recordado.",
  ui_story_5061_50610201_9_dialog_content = "De hecho, ¡probablemente ya te habría preparado una agradable y caliente taza de té!",
  ui_story_5061_50610201_10_dialog_content = "(Suspiro) ¡Ya extraño estar de vuelta en Lumopolis e Illumina con todos! Al menos no me estaría congelando hasta morir.",
  ui_story_5061_50610201_11_dialog_content = "Lamento que no hayamos podido ir contigo esta vez...",
  ui_story_5061_50610201_12_dialog_content = "¡Pero te prometo que nos divertiremos mucho juntos en Northland la próxima vez!",
  ui_story_5061_50610201_13_dialog_content = "Y si Carleen viene, ¡incluso podría llevarnos a dar un paseo en carruaje!",
  ui_story_5061_50610201_14_dialog_content = "(Si alguna vez hay una próxima vez, preferiría quedarme en mi Coloso...)",
  ui_story_5061_50610201_15_dialog_content = "Está bien, de verdad. Solo estoy un poco aburrido aquí afuera y no se me ocurre nada más de qué hablar.",
  ui_story_5061_50610201_16_dialog_content = "Lo sé. Es fácil sentirse solo cuando viajas por la nieve por tu cuenta. ¿Por qué no pruebas el nuevo comunicador que el oficial Gronru te dio?",
  ui_story_5061_50610201_17_dialog_content = "Capta todo tipo de sonidos y señales de todo el mundo. Incluso si estás solo en el Colossus, ¡estoy seguro de que te ayudará a levantar el ánimo!",
  ui_story_5061_50610201_18_dialog_content = "Quizás puedas escuchar el sonido de la maquinaria de Illumina, ¡o incluso una transmisión de música desde Umbraton! Suena increíble, ¿verdad?",
  ui_story_5061_50610201_19_dialog_content = "... Sería mucho más increíble si pudiera elegir realmente qué escuchar...",
  ui_story_5061_50610201_20_dialog_content = "Supongo que simplemente tendrás que confiar en el oficial Gronru!",
  ui_story_5061_50610201_21_dialog_content = "Asegúrate de cuidarte bien allá afuera. Y si ves algo interesante, recuerda contarnos para que podamos verlo juntos algún día.",
  ui_story_5061_50610201_22_dialog_content = "De todos modos, mientras Queen Bethlehem esté presente, Northland debería estar perfectamente seguro. ¡De lo contrario, nunca habría estado bien dejarte solo!",
  ui_story_5061_50610201_23_dialog_content = "Bueno, el entrenamiento está a punto de comenzar, así que debería irme. ¡Hablamos pronto!",
  ui_story_5061_50610201_24_dialog_content = "Está bien...",
  ui_story_5061_50610201_25_dialog_content = "...",
  ui_story_5061_50610201_26_dialog_content = "¿Porque el tiempo y el lugar están equivocados?",
  ui_story_5061_50610201_26X1_dialog_content = "Northland realmente es... Exactamente como Carleen y los demás lo describen...",
  ui_story_5061_50610201_27_dialog_content = "La Northland de hoy ya no se parece al encantador cuento de hadas que Carleen me describió una vez...",
  ui_story_5061_50610201_27X1_dialog_content = "Es completamente diferente a lugares como Lumopolis y las Ciudades Bajas.",
  ui_story_5061_50610201_28_dialog_content = "<color=#e8d9bb>Vastos, fríos y misteriosos, los bosques se extienden infinitamente mientras las cumbres de las montañas se alzan altas, grandiosas y majestuosas.</color>",
  ui_story_5061_50610201_29_dialog_content = "<color=#e8d9bb>Quedan escasas huellas de civilización en esta tierra, como si nada hubiera cambiado a lo largo de miles de años.</color>",
  ui_story_5061_50610201_30_dialog_content = "Está tan tranquilo aquí...",
  ui_story_5061_50610201_31_dialog_content = "... Tal vez debería probar el comunicador de Gronru. Cualquier cosa para romper este pesado silencio.",
  ui_story_5061_50610201_32_option_content = "Activar Comunicador",
  ui_story_5061_50610201_33_dialog_content = "(Click) Zumbido, zumbido...",
  ui_story_5061_50610201_34_dialog_content = "Zumbido, zumbido...",
  ui_story_5061_50610201_35_dialog_content = "... ¡No funciona en absoluto!",
  ui_story_5061_50610201_36_dialog_content = "Todo este ruido estático me está dando dolor de cabeza. Supongo que simplemente lo apagaré...",
  ui_story_5061_50610201_37_dialog_content = "... ¿A... Alguien?!",
  ui_story_5061_50610201_38_dialog_content = "... Esto es... el... ¡Solicitando ayuda!",
  ui_story_5061_50610201_39_dialog_content = "¿Eh? ¿Una llamada de socorro?!",
  ui_story_5061_50610201_40_dialog_content = "Repito: Esta es la cresta noreste del Pico Cedar en la frontera de Northland, a una altitud de 3,200 metros.",
  ui_story_5061_50610201_41_dialog_content = "Encontré a alguien atrapado en el hielo. La situación se ve grave y no puedo realizar un rescate.",
  ui_story_5061_50610201_42_dialog_content = "A cualquiera que pueda estar escuchando, por favor vengan equipados con herramientas para romper hielo y equipo de calefacción para el rescate!",
  ui_story_5061_50610201_43_dialog_content = "Pico de Cedro... ¡No está lejos de aquí en absoluto!",
  ui_story_5061_50610201_44_dialog_content = "¡Solo espera! ¡La ayuda está en camino!",
  ui_story_5061_50610201_45_dialog_content = "(El clima y el terreno dificultaron aterrizar rápidamente... Solo espero no llegar demasiado tarde.)",
  ui_story_5061_50610201_46_dialog_content = "¿Hola? ¿Hay alguien ahí? ¡Recibí una llamada de socorro desde esta ubicación!",
  ui_story_5061_50610201_47_dialog_content = "¡Ey! ¿Alguien puede oírme?! Supongo que tendré que usar mis poderes... Fuerza Boo—¡Vaya!",
  ui_story_5061_50610201_48_dialog_content = "(¡La nieve está tan profunda! Y no hay más que nieve a la vista... ¿Podrían estar enterrados en algún lugar debajo de todo eso?!)",
  ui_story_5061_50610201_49_dialog_content = "<color=#e8d9bb>Crujido-</color>",
  ui_story_5061_50610201_50_dialog_content = "¿Qué fue eso?",
  ui_story_5061_50610201_51_dialog_content = "<color=#e8d9bb>Crujiente-</color>",
  ui_story_5061_50610201_52_dialog_content = "Ja...",
  ui_story_5061_50610201_53_dialog_content = "¿Qué es ese sonido...? ¿Podría ser que alguien esté enterrado en la nieve?!",
  ui_story_5061_50610201_54_dialog_content = "¡Solo espera, te sacaré de ahí!",
  ui_story_5061_50610201_55_dialog_content = "Jaah... Jaah...",
  ui_story_5061_50610201_56_dialog_content = "rugir—",
  ui_story_5061_50610201_57_dialog_content = "¿¡¿Eh!?!",
  ui_story_5061_50610201_58_dialog_content = "¡Activando técnica de emergencia!",
  ui_story_5061_50610201_59_dialog_content = "¡Gaaah!",
  ui_story_5061_50610201_60_dialog_content = "¡Ponte detrás de mí! ¡Me encargaré de esto!",
  ui_story_5061_50610202_1_dialog_content = "Gruñido...",
  ui_story_5061_50610202_2_dialog_content = "Uf, estoy salvado. Gracias...",
  ui_story_5061_50610202_3_dialog_content = "Disculpe, pero debe ser...",
  ui_story_5061_50610202_4_dialog_content = "¡Colores! ¡Vi Lumina de todo tipo de colores durante nuestra batalla hace un momento! ¡Estaban tan claros como el día!",
  ui_story_5061_50610202_5_dialog_content = "Fue como si el camino a la victoria apareciera en mi mente... ¡Sabía exactamente lo que tenía que hacer!",
  ui_story_5061_50610202_6_dialog_content = "Me moví con el flujo de Lumina como una hoja en el viento. Todo se sentía tan natural...",
  ui_story_5061_50610202_7_dialog_content = "¿Pero cómo? ¡¿Cómo podría ser eso?! ¡Tengo que saber más al respecto! ¡Tengo que hacerlo!",
  ui_story_5061_50610202_8_dialog_content = "¡Debes ser el Caelestite del que he estado oyendo últimamente! ¿Te importaría responder algunas de mis preguntas? Me encantaría aprender más sobre tus habilidades y sobre tus experiencias pilotando el Colossus.",
  ui_story_5061_50610202_9_dialog_content = "¡E-Espera un segundo! Estaría encantado de hablar, pero ¿no deberíamos al menos presentarnos? Mi nombre es PlayerName.",
  ui_story_5061_50610202_10_dialog_content = "¡Oh! P-Perdón por eso, a veces tiendo a emocionarme un poco... Es una mala costumbre mía, pero espero no haberte molestado ni nada, ¿verdad?",
  ui_story_5061_50610202_11_dialog_content = "Mi nombre es Antony y soy un erudito popular. ¿Viniste por la llamada de socorro que envié?",
  ui_story_5061_50610202_12_dialog_content = "El clima es tan extremo aquí que quedé enterrado en la nieve. Todo lo que pude hacer fue sentarme y esperar hasta escuchar que se acercaba ayuda...",
  ui_story_5061_50610202_13_dialog_content = "¡Menos mal que pude escuchar tu llegada!",
  ui_story_5061_50610202_14_dialog_content = "Así es. Tampoco estoy construido exactamente para este tipo de ambiente. No podía sentir a nadie aquí, pensé que estaba rescatando a una persona, pero resultó ser un Eclipsite...",
  ui_story_5061_50610202_15_dialog_content = "De todos modos, también mencionaste algo sobre una persona atrapada, ¿no es cierto?",
  ui_story_5061_50610202_16_dialog_content = "¡Es cierto! Pero la situación es... un poco difícil de creer. Es completamente diferente de lo que pensaba originalmente...",
  ui_story_5061_50610202_17_dialog_content = "Aquí, ven conmigo.",
  ui_story_5061_50610202_18_dialog_content = "Oh, y cuidado con esos carámbanos. Algunos de ellos tienen Eclipsites atrapados dentro.",
  ui_story_5061_50610202_19_dialog_content = "Pero hay montones de ellos...",
  ui_story_5061_50610202_20_dialog_content = "Aquí está ella. Adelante, echa un vistazo en el hielo.",
  ui_story_5061_50610202_21_dialog_content = "¿Es eso... una niña dentro del hielo?",
  ui_story_5061_50610202_22_dialog_content = "... ¿¡Sigue viva?!",
  ui_story_5061_50610202_23_dialog_content = "Sí, eso creo.",
  ui_story_5061_50610202_24_dialog_content = "A pesar de estar atrapada en el hielo, su cuerpo no muestra signos visibles de haber muerto congelada.",
  ui_story_5061_50610202_25_dialog_content = "De hecho, parece que simplemente está durmiendo. Como si esta tumba congelada no fuera diferente a una cama...",
  ui_story_5061_50610202_26_dialog_content = "¡Tal vez pueda conectarme con ella telepáticamente!",
  ui_story_5061_50610202_27_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50610202_28_dialog_content = "Nngh... ¿Eh...?",
  ui_story_5061_50610202_29_dialog_content = "¿Cuándo... me quedé dormido...?",
  ui_story_5061_50610202_30_dialog_content = "¿Cómo ocurrió esto? Tenía... algo importante que hacer...",
  ui_story_5061_50610202_31_dialog_content = "Si fallo... Todos los pueblos cercanos, no, todo Northland... ¡Mi hermana!",
  ui_story_5061_50610202_32_dialog_content = "¡Realmente está viva! ¡Y su mente también está respondiendo muy intensamente!",
  ui_story_5061_50610202_33_dialog_content = "¡Eso es maravilloso! ¿Deberíamos intentar sacarla del hielo? O tal vez nuestra mejor opción sea derretirlo primero...",
  ui_story_5061_50610202_34_dialog_content = "Espera, estoy sintiendo algunas fluctuaciones de energía extrañas cerca...",
  ui_story_5061_50610202_35_dialog_content = "Y parece que ella es la fuente de eso. Debe tener una gran cantidad de Lumina almacenada en su cuerpo...",
  ui_story_5061_50610202_36_dialog_content = "¡Y cuando la desperté con mis poderes, comenzó a usar su Luminática inconscientemente!",
  ui_story_5061_50610202_37_dialog_content = "<color=#e8d9bb>(Sonidos de grietas)</color>",
  ui_story_5061_50610202_38_dialog_content = "Parece que el hielo está comenzando a separarse.",
  ui_story_5061_50610202_39_dialog_content = "La Lumina que creó este hielo está fluyendo rápidamente hacia afuera. A este ritmo, ella podría ser capaz de liberarse. ¡Esto es genial!",
  ui_story_5061_50610202_40_dialog_content = "Genial, ¡mi pie! ¿Y si provoca una avalancha o algo así?!",
  ui_story_5061_50610202_41_dialog_content = "Necesitamos retroceder a una distancia segura antes de que terminemos enterrados junto con el resto de esos Eclipsites.",
  ui_story_5061_50610202_42_dialog_content = "rugir—",
  ui_story_5061_50610202_43_dialog_content = "¿¡Eso es todo lo que se necesitó para sacarlos?!",
  ui_story_5061_50610202_44_dialog_content = "Oh no... ¡Van directamente hacia nosotros!",
  ui_story_5061_50610202_45_dialog_content = "Los Eclipsites realmente son criaturas fascinantes. Si nuestras vidas no estuvieran en tanto peligro, me encantaría estudiarlos más de cerca...",
  ui_story_5061_50610202_46_dialog_content = "<color=#e8d9bb>(Gruñidos)</color>",
  ui_story_5061_50610202_47_dialog_content = "Afortunadamente, no son muchos. Debería poder llamar su atención mientras tú escapas.",
  ui_story_5061_50610202_48_dialog_content = "¿Vas a enfrentarte a todos ellos por ti mismo?! ¡No es que estén precisamente interesados en tu investigación, sabes!",
  ui_story_5061_50610202_49_dialog_content = "No te preocupes. Como un semi-humano, soy más que capaz de defenderme por mí mismo. Además, he estado en este tipo de situaciones muchas veces.",
  ui_story_5061_50610202_50_dialog_content = "Al menos, debería poder sobrevivir a sus ataques hasta que se cansen.",
  ui_story_5061_50610202_51_dialog_content = "Esa es una estrategia... muy única.",
  ui_story_5061_50610202_52_dialog_content = "Pero ya que estoy aquí, haré todo lo posible para ayudarte a ganar. Soy un Caelestita, no te defraudaré.",
  ui_story_5061_50610202_53_dialog_content = "¡Te cubro! ¡Vamos a enseñarles a estos monstruos lo que pasa cuando seguimos el flujo de Lumina!",
  ui_story_5061_50610202_54_dialog_content = "¡Roaaar—!",
  ui_story_5061_50610202_55_dialog_content = "¡Urgh! N-no he terminado aún...",
  ui_story_5061_50610202_56_dialog_content = "¡Concéntrate, Antony! Necesitas seguir el camino de Lumina a tus pies—¿Eh?",
  ui_story_5061_50610202_57_dialog_content = "M-Mis pies... ¿están congelados?!",
  ui_story_5061_50610202_58_dialog_content = "La temperatura está bajando drásticamente...",
  ui_story_5061_50610202_59_dialog_content = "¿Quién... está ahí?",
  ui_story_5061_50610202_60_dialog_content = "¡Graagh!",
  ui_story_5061_50610302_1_dialog_content = "¡Whoa!",
  ui_story_5061_50610302_2_dialog_content = "La ventisca finalmente cesó... ¿Estás bien?",
  ui_story_5061_50610302_3_dialog_content = "Estoy bien, pero ¿y ella...?",
  ui_story_5061_50610302_4_dialog_content = "...",
  ui_story_5061_50610302_5_dialog_content = "¡Cuidado!",
  ui_story_5061_50610302_6_dialog_content = "Su pulso y respiración son normales, pero está fría como el hielo y su rostro se ve un poco pálido...",
  ui_story_5061_50610302_7_dialog_content = "¿Qué hacemos ahora?",
  ui_story_5061_50610302_8_dialog_content = "Despiértala e intenta mantenerla consciente. Voy a buscar un camino hacia el pueblo más cercano.",
  ui_story_5061_50610302_9_dialog_content = "Sin problema.",
  ui_story_5061_50610302_10_dialog_content = "Perdón si esto es un poco brusco... ¡Pero la mejor manera de despertarte completamente es entrando en tu mente de nuevo!",
  ui_story_5061_50610302_11_dialog_content = "¡Despierta!!!",
  ui_story_5061_50610302_12_dialog_content = "¡¿Ah?!",
  ui_story_5061_50610302_13_option_content = "Eh, hola... ¿Estás bien?",
  ui_story_5061_50610302_14_dialog_content = "Lo siento por despertarte así. ¿Estás lastimado en absoluto? ¿Recuerdas algo?",
  ui_story_5061_50610302_15_dialog_content = "¿Quién eres? Nunca te he visto antes en mi vida...",
  ui_story_5061_50610302_16_option_content = "Hmm, qué extraño.",
  ui_story_5061_50610302_17_dialog_content = "¿Eres una especie de diosa de las paletas de hielo? ¡Ese poder que desataste antes fue una locura!",
  ui_story_5061_50610302_18_dialog_content = "¿A-A qué te refieres con diosa de las paletas de hielo?",
  ui_story_5061_50610302_19_dialog_content = "¿Quién eres y de qué estás hablando?!",
  ui_story_5061_50610302_20_dialog_content = "Bueno, mi nombre es PlayerName y soy un Caelestita. Mi amigo y yo te encontramos atrapado en el hielo...",
  ui_story_5061_50610302_21_dialog_content = "... O al menos estabas atrapado, pero luego lograste salir hace solo unos minutos.",
  ui_story_5061_50610302_22_dialog_content = "¿Cómo te sientes? ¿Te duele algo?",
  ui_story_5061_50610302_23_dialog_content = "Un Caelestita...? ¿Qué estaría haciendo un Caelestita aquí...",
  ui_story_5061_50610302_24_dialog_content = "El hielo... Recuerdo luchar contra una horda de Eclipsites, pero luego...",
  ui_story_5061_50610302_25_dialog_content = "Espera... ¿Estoy muerto? ¿Podría ser este lugar el más allá...?",
  ui_story_5061_50610302_26_dialog_content = "... Incorrecto en todos los aspectos. Estamos en una montaña cerca de la frontera de Northland, y seguimos muy vivos.",
  ui_story_5061_50610302_27_dialog_content = "Una montaña cerca de la frontera de Northland... ¡Así es! ¡Vine aquí buscando a mi hermana!",
  ui_story_5061_50610302_28_dialog_content = "<color=#FFB400>Hermana</color>... Dime, ¿lograron rescatar también a los otros <color=#FFB400>patrulleros</color>?",
  ui_story_5061_50610302_29_dialog_content = "¿Quieres decir que hay otras personas atrapadas en el hielo?",
  ui_story_5061_50610302_30_dialog_content = "No, me refiero a...",
  ui_story_5061_50610302_31_dialog_content = "Espera, ¿quieres decir que no lo sabes? ¡Aquí es donde ocurrió la <color=#FFB400>tormenta de aurora</color>! ¡La Corte envió a docenas de patrulleros para investigar!",
  ui_story_5061_50610302_32_dialog_content = "Excepto... Ninguno de ellos regresó. ¿Estás seguro de que no viste a nadie más?",
  ui_story_5061_50610302_33_dialog_content = "(No sabía nada de esto cuando llegué a Northland... Antony tampoco mencionó nada.)",
  ui_story_5061_50610302_34_dialog_content = "Mi nombre es Zarya. Mi hermana, Alina, es la capitana de los patrulleros. Dime, ¿de verdad no viste a nadie más por aquí?",
  ui_story_5061_50610302_35_dialog_content = "Lo siento mucho, pero no he visto... Espera, ¿qué es eso?!",
  ui_story_5061_50610302_36_dialog_content = "rugir—",
  ui_story_5061_50610302_37_dialog_content = "(¡Mierda! Me quedé tan atrapado hablando con ella. ¡Olvidé por completo vigilar nuestro entorno!)",
  ui_story_5061_50610302_38_dialog_content = "... ¡Florece, Luz de Hielo!",
  ui_story_5061_50610302_39_dialog_content = "Ugh—",
  ui_story_5061_50610302_40_dialog_content = "(Tan poderosa... Aunque no esté en su máxima fuerza, ¡eliminó a cuatro Eclipsites con un solo ataque!)",
  ui_story_5061_50610302_41_dialog_content = "Hay Eclipsites aquí... ¡Eso significa que mi hermana está en aún más peligro!",
  ui_story_5061_50610302_42_dialog_content = "¡Tengo que encontrarla de inmediato! ¡Alina!",
  ui_story_5061_50610302_43_dialog_content = "¡Espera! ¡Despertaste hace poco! ¡Es demasiado peligroso pelear en tu estado actual!",
  ui_story_5061_50610302_44_dialog_content = "¡Pero mi hermana también podría estar en peligro!",
  ui_story_5061_50610302_45_dialog_content = "No entiendo cómo ni por qué, ¡pero finalmente tengo una forma de luchar contra los Eclipsites ahora!",
  ui_story_5061_50610302_46_dialog_content = "Si no puedo salvar a mi familia con el poder, entonces ¿de qué sirvo—",
  ui_story_5061_50610302_47_dialog_content = "<color=#e8d9bb>¡Plaf!</color>",
  ui_story_5061_50610302_48_dialog_content = "¡Oye! ¡Cálmate! No habrá esperanza para ti si te desmayas en un lugar como este.",
  ui_story_5061_50610302_49_dialog_content = "Si algo me pasa, por favor... Ayúdame a encontrar a mi hermana y dile, dile que no quiero que me dejen sola de nuevo.",
  ui_story_5061_50610302_50_dialog_content = "...",
  ui_story_5061_50610302_51_dialog_content = "¡Oye—!",
  ui_story_5061_50610302_52_dialog_content = "Aliento de Primavera—",
  ui_story_5061_50610302_53_dialog_content = "¿Son estos... capullos de flores? ¿Y por qué de repente me siento tan cómodo...?",
  ui_story_5061_50610302_54_dialog_content = "Perdón, pero ¿eres PlayerName?",
  ui_story_5061_50610302_55_dialog_content = "Sí, soy yo.",
  ui_story_5061_50610302_56_dialog_content = "Eh, h-hola... Mi nombre es Leah y soy un patrullero de Northland... Q-quiero decir, un patrullero en formación.",
  ui_story_5061_50610302_57_dialog_content = "El Sr. Antony me pidió que guiara a todos hacia un lugar seguro.",
  ui_story_5061_50610302_58_dialog_content = "Q-Que no cunda el pánico, estoy muy familiarizado con los senderos de montaña y los escondites en esta área. Juro guiar a todos de regreso al alcance protector de Queen Bethlehem de manera segura.",
  ui_story_5061_50610302_59_dialog_content = "Um, creo que eso es todo. ¿Me olvidé de algo?",
  ui_story_5061_50610401_1_dialog_content = "Aquí, toma algunas frutas recién recolectadas...",
  ui_story_5061_50610401_2_dialog_content = "Es excelente para protegerse del frío.",
  ui_story_5061_50610401_3_dialog_content = "Quería traer más medicamentos y suministros, pero nuestras existencias ya son muy limitadas. Lo siento...",
  ui_story_5061_50610401_4_dialog_content = "Por favor, no te disculpes por eso, ya estamos agradecidos por tu ayuda. ¿No quieres algo, Antony?",
  ui_story_5061_50610401_5_dialog_content = "¡Oh! Lo siento, no estaba prestando atención hace un momento.... Gracias.",
  ui_story_5061_50610401_6_dialog_content = "Entonces, ¿cómo está Zarya?",
  ui_story_5061_50610401_7_dialog_content = "Tal como dijiste antes, su condición está lejos de ser normal. También detecto una enorme cantidad de Lumina en su cuerpo.",
  ui_story_5061_50610401_8_dialog_content = "Para ser honesto, un Auroriano común no sería capaz de soportar tanta Lumina.",
  ui_story_5061_50610401_9_dialog_content = "Sin embargo, no solo pudo sobrevivir estando atrapada en hielo, sino que también logró salir de él por sí misma. Eso no es algo común.",
  ui_story_5061_50610401_10_dialog_content = "En efecto. También me sorprendió descubrir que seguía viva cuando exploré su mente.",
  ui_story_5061_50610401_11_dialog_content = "Comunicarse con ella no ha sido fácil. No para de hablar sobre patrulleros, su hermana y algo acerca de la \"Aurora tormentosa\"...",
  ui_story_5061_50610401_12_dialog_content = "Ella no escuchó ni una palabra de lo que dije.",
  ui_story_5061_50610401_13_dialog_content = "Los patrulleros han estado bien y nadie ha desaparecido últimamente, ¿verdad, Leah?",
  ui_story_5061_50610401_14_dialog_content = "¡Oh! ¿E-Estabas hablando conmigo...?",
  ui_story_5061_50610401_15_dialog_content = "Sí, tienes razón. Todos los patrulleros han regresado de sus puestos, sanos y salvos.",
  ui_story_5061_50610401_16_dialog_content = "Eso coincide con mi entendimiento también. Después de todo, esto es Northland; mientras nos quedemos dentro de sus fronteras, deberíamos estar perfectamente seguros.",
  ui_story_5061_50610401_17_dialog_content = "Todos lo sabemos. En caso de emergencia, todos sabemos que debemos retirarnos al territorio del Queen para estar seguros.",
  ui_story_5061_50610401_18_dialog_content = "Tengo una pregunta.",
  ui_story_5061_50610401_19_dialog_content = "El Faro de Northland... ¿Realmente puede proteger a todo Northland con solo el poder de Queen Bethlehem?",
  ui_story_5061_50610401_19X1_dialog_content = "Desde mi primera visita a Northland, he notado que todos hablan constantemente sobre la protección otorgada por el Queen y el Faro.",
  ui_story_5061_50610401_20_dialog_content = "Después de mi último viaje al Palacio de Invierno, no he dejado de preocuparme por su bienestar.",
  ui_story_5061_50610401_20X1_dialog_content = "Sé que Queen Bethlehem es uno de los Aurorianos más nobles y poderosos en todo Astra.",
  ui_story_5061_50610401_21_dialog_content = "Ella me dijo que lo peor ya había quedado en el pasado y que no debería preocuparme más... Pero, ¿realmente está bien?",
  ui_story_5061_50610401_21X1_dialog_content = "¿Y qué hace que el Faro sea tan especial? ¿Realmente puede cubrir a toda una nación con una barrera protectora?",
  ui_story_5061_50610401_22_dialog_content = "Su Majestad es... ¡la persona más confiable y segura que conozco! Si ella dice algo, ¡entonces debe ser cierto!",
  ui_story_5061_50610401_22X1_dialog_content = "¡Y sí, realmente es así de especial! Mientras el Faro siga encendido, ningún Eclipsite podrá cruzar a Northland.",
  ui_story_5061_50610401_23_dialog_content = "Estoy seguro de que hay mucho más en el Faro que eso. Después de todo, como nuestra única defensa contra los Eclipsites durante más de un milenio, debe contener todo tipo de secretos dentro de sus muros.",
  ui_story_5061_50610401_23X1_dialog_content = "En pocas palabras, el Faro es la estructura de defensa única de Northland, al igual que Lumopolis e Illumina tienen las suyas.",
  ui_story_5061_50610401_24_dialog_content = "Como residentes de Northland, creer de todo corazón en nuestra reina es el primer paso para ayudarla.",
  ui_story_5061_50610401_24X1_dialog_content = "El Faro es nuestra mayor arma, así como nuestra mayor defensa.",
  ui_story_5061_50610401_25_dialog_content = "Sin embargo, estoy mucho más interesado en la Aurorastorm...",
  ui_story_5061_50610401_26_dialog_content = "¿Estás seguro de que la señorita Zarya lo dijo?",
  ui_story_5061_50610401_27_dialog_content = "Sí, y también lo recuerdo claramente. Estaba decidida a encontrar a su hermana y a los otros patrulleros, por eso salió aquí en primer lugar.",
  ui_story_5061_50610401_28_dialog_content = "Pero aparte de lo que sucedió con ella, nada más en esta área parece fuera de lo común.",
  ui_story_5061_50610401_29_dialog_content = "Entiendo. Me preocupa porque últimamente he estado buscando pistas relacionadas con la Aurora tormentosa.",
  ui_story_5061_50610401_30_dialog_content = "De hecho, es la razón principal por la que vine a Pico de Cedro.",
  ui_story_5061_50610401_31_dialog_content = "Creo que mi próximo paso es realizar una encuesta exhaustiva del área. Solo entonces podré llegar a una conclusión más específica.",
  ui_story_5061_50610401_32_dialog_content = "Con un poco de suerte, podré averiguar más sobre la situación de la señorita Zarya!",
  ui_story_5061_50610401_33_dialog_content = "Contamos contigo, Antony. También me gustaría saber más sobre la extraña Lumina que sentí de ella antes.",
  ui_story_5061_50610401_34_dialog_content = "Esa energía era más pura que cualquier cosa que haya experimentado...",
  ui_story_5061_50610401_35_dialog_content = "Comprendido. Por favor, sigue cuidándola bien mientras reúno más información.",
  ui_story_5061_50610401_36_dialog_content = "Eh, ¿debería intentar encontrar a un médico?",
  ui_story_5061_50610401_37_dialog_content = "No creo que sea necesario. Por lo que puedo ver, ella no está enferma ni herida. Mi primeros auxilios deberían ser suficientes por ahora.",
  ui_story_5061_50610401_38_dialog_content = "Realmente sabes lo que haces, Antony. No solo eres un luchador fuerte, sino que incluso sabes cómo brindar tratamiento médico!",
  ui_story_5061_50610401_39_dialog_content = "También tengo curiosidad por saber más sobre tu investigación acerca del origen de los Aurorianos.",
  ui_story_5061_50610401_40_dialog_content = "¿Estudiaste en Lumopolis o Illumina, por casualidad?",
  ui_story_5061_50610401_41_dialog_content = "¿Mmm? Para nada, ¿por qué preguntas?",
  ui_story_5061_50610401_42_dialog_content = "Oh, es que una buena amiga mía estudió en el extranjero en el pasado y realmente aprendió mucho en ese tiempo. Solo tenía curiosidad por saber si tuviste una experiencia similar.",
  ui_story_5061_50610401_43_dialog_content = "Oh, ya veo. No, mi única educación formal provino de clases de alfabetización ofrecidas a niños en las zonas fronterizas.",
  ui_story_5061_50610401_44_dialog_content = "Eh, ¿clases de alfabetización?",
  ui_story_5061_50610401_45_dialog_content = "¡Así es! Gracias a ellos, pude leer y entender libros, y escribir mis descubrimientos.",
  ui_story_5061_50610401_46_dialog_content = "Lo siento si te decepcioné de alguna manera, no soy un erudito famoso de una academia prestigiosa.",
  ui_story_5061_50610401_47_dialog_content = "¿Estás bromeando? Si acaso, ¡eso es aún más increíble!",
  ui_story_5061_50610401_48_dialog_content = "Nunca recibí una educación formal en Astra tampoco. Todo mi conocimiento me fue transmitido por mi familia...",
  ui_story_5061_50610401_49_dialog_content = "¡Pero eres un estudiante mucho mejor de lo que yo jamás seré!",
  ui_story_5061_50610401_50_dialog_content = "¡No hay nada de malo en eso! No importa cómo ni dónde adquieras conocimientos, siempre y cuando persista tu auténtica sed de aprendizaje y exploración.",
  ui_story_5061_50610401_51_dialog_content = "¡Salgo ahora!",
  ui_story_5061_50610401_52_dialog_content = "Bien, ten cuidado ahí fuera.",
  ui_story_5061_50610401_53_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5061_50610401_54_dialog_content = "(Antony cerró la puerta tan suavemente... Probablemente para evitar despertar a Zarya.)",
  ui_story_5061_50610401_55_dialog_content = "(... Después de luchar y pelear en la nieve durante tanto tiempo, el calor de esta habitación me hace sentir más somnoliento.)",
  ui_story_5061_50610401_56_dialog_content = "(Parece que Zarya no va a despertar pronto. Supongo que también debería intentar descansar un poco.)",
  ui_story_5061_50610402_1_dialog_content = "(¿Eh? ¿Adónde fueron esos Eclipsites? Hace demasiado calor aquí y tengo la boca tan seca...)",
  ui_story_5061_50610402_2_dialog_content = "<color=#e8d9bb>Crujiente-</color>",
  ui_story_5061_50610402_3_dialog_content = "(Oh... Solo fue un sueño.)",
  ui_story_5061_50610402_4_dialog_content = "¿Está todo bien? Señorita Zarya?",
  ui_story_5061_50610402_5_dialog_content = "N-No es nada! Simplemente no sabía cómo usar esta tetera... No me di cuenta de que todavía estaba caliente.",
  ui_story_5061_50610402_6_dialog_content = "Eh, tú eres la paciente, señorita Zarya. Creo que deberías recostarte de nuevo, por favor...",
  ui_story_5061_50610402_7_dialog_content = "¡Me siento bien ahora, lo prometo! Además, solo estaba intentando servirle un vaso de agua a esta persona...",
  ui_story_5061_50610402_8_dialog_content = "Emm... Zarya, ¿estás despierto? ¿Qué están haciendo ustedes dos?",
  ui_story_5061_50610402_9_dialog_content = "¿Y quién me puso este abrigo?",
  ui_story_5061_50610402_10_dialog_content = "Eso fue obra de la señorita Zarya. Cuando despertó, te encontró durmiendo a su lado...",
  ui_story_5061_50610402_11_dialog_content = "Se sintió tan en deuda contigo por tu amabilidad que me pidió que te trajera este abrigo!",
  ui_story_5061_50610402_12_dialog_content = "N-No tengo idea de lo que estás hablando. Quiero decir, sí, él me ayudó mucho en la montaña antes...",
  ui_story_5061_50610402_13_dialog_content = "Pero también lo rescaté de un grupo de Eclipsites sedientos de sangre. Seguramente eso nos hace iguales, ¿verdad...?",
  ui_story_5061_50610402_14_dialog_content = "Además, como forastero, merece recibir la verdadera hospitalidad de Northland, ¿no crees?!",
  ui_story_5061_50610402_15_dialog_content = "...",
  ui_story_5061_50610402_16_dialog_content = "T-Tal vez es porque todavía estoy en entrenamiento, pero no entendí realmente nada de lo que dijo hace un momento, señorita Zarya...",
  ui_story_5061_50610402_17_dialog_content = "¡Ah! No, eso no tiene nada que ver con eso. Es solo que...",
  ui_story_5061_50610402_18_dialog_content = "Gracias.",
  ui_story_5061_50610402_19_dialog_content = "Lo aprecio, pero realmente deberías intentar quedarte en la cama y descansar. ¿Todavía recuerdas lo que pasó en la montaña?",
  ui_story_5061_50610402_20_dialog_content = "Lo hago. Iba a buscar a mi hermana, pero tú me detuviste... ¿Por qué hiciste eso?!",
  ui_story_5061_50610402_21_dialog_content = "Si no lo hubiera hecho, habrías terminado congelado de nuevo o en el estómago de un Eclipsite. ¿Te suena bien alguna de esas opciones?",
  ui_story_5061_50610402_22_dialog_content = "No querías escuchar en absoluto, pero terminé teniendo que llevarte de regreso todo el camino.",
  ui_story_5061_50610402_23_dialog_content = "¿T-Tú qué? ¿Me llevaste montaña abajo...?",
  ui_story_5061_50610402_24_dialog_content = "E-entiendo... Pero nunca te pedí que hicieras eso, ¡sabes! ¡Habría estado bien si me hubieras dejado allí afuera!",
  ui_story_5061_50610402_25_dialog_content = "¿Podrías dejarlo ya? ¡Pareces un niño pequeño en este momento!",
  ui_story_5061_50610402_26_dialog_content = "... Pero aún así, sé que debería recompensarte adecuadamente por salvarme la vida. Eso no es algo que diría un niño, ¿verdad?",
  ui_story_5061_50610402_27_dialog_content = "Está bien, está bien... Pero si alguien merece tu agradecimiento, son el Sr. Antony y Leah. Ellos son los que te encontraron y te trajeron medicina.",
  ui_story_5061_50610402_28_dialog_content = "Sí, lo sé.",
  ui_story_5061_50610402_29_dialog_content = "¿Te sientes mejor ahora? Si estás dispuesto a responder algunas preguntas, tal vez podamos encontrar una manera de encontrar a tu hermana.",
  ui_story_5061_50610402_30_dialog_content = "Seguro.",
  ui_story_5061_50610402_31_dialog_content = "Primero que nada, ¿qué estabas haciendo atrapado en el hielo allá arriba?",
  ui_story_5061_50610402_32_dialog_content = "... Preferiría no hablar de ello.",
  ui_story_5061_50610402_33_dialog_content = "¡Oye! ¡Acabas de aceptar hablar las cosas y ahora te estás retractando de tu palabra?!",
  ui_story_5061_50610402_34_dialog_content = "T-Tienes razón, lo siento.",
  ui_story_5061_50610402_35_dialog_content = "Como mencioné antes, todo el equipo enviado por la Corte para investigar la Aurorastorm nunca más fue visto ni escuchado.",
  ui_story_5061_50610402_36_dialog_content = "Mi hermana también estaba entre ellos.",
  ui_story_5061_50610402_37_dialog_content = "Fui a su última ubicación conocida y busqué durante horas. Finalmente, logré escuchar la voz de mi hermana cerca, solo para encontrarlos siendo atacados por una horda de Eclipsites.",
  ui_story_5061_50610402_38_dialog_content = "Había tantos de ellos y me preocupaba no llegar a tiempo con mi hermana.",
  ui_story_5061_50610402_39_dialog_content = "Así que mientras la batalla continuaba, me escondí bajo un montón de cadáveres de Eclipsites y recé con todo mi corazón...",
  ui_story_5061_50610402_40_dialog_content = "Rogué encontrar la fuerza necesaria para rescatar a mi hermana...",
  ui_story_5061_50610402_41_dialog_content = "De repente, como si mis plegarias hubieran sido escuchadas, un enorme poder surgió dentro de mí. Desafortunadamente, perdí completamente el control de él y mi Lumina se desató por todo el campo de batalla.",
  ui_story_5061_50610402_42_dialog_content = "Los Eclipsites fueron prácticamente exterminados, pero al mismo tiempo, terminé atrapado en una tumba congelada creada por mis propios Luminatics.",
  ui_story_5061_50610402_43_dialog_content = "Allí permanecí inactivo... Hasta que me despertaste hoy.",
  ui_story_5061_50610402_44_dialog_content = "Entonces, ¿te atrapaste en el hielo? Tu historia se vuelve cada vez más loca, ¿sabes?",
  ui_story_5061_50610402_45_dialog_content = "No es que quisiera que esto sucediera... Nunca he sido especialmente bueno controlando mi poder.",
  ui_story_5061_50610402_46_dialog_content = "¡Adelante, ríete! Mientras me ayudes a encontrar a mi hermana después, puedes reírte todo lo que quieras...",
  ui_story_5061_50610402_47_dialog_content = "Todavía tengo dificultades para distinguir mis recuerdos de la realidad...",
  ui_story_5061_50610402_48_dialog_content = "Comprendo.",
  ui_story_5061_50610402_49_dialog_content = "Leah, ¿te importaría contarle a Zarya lo que me dijiste antes?",
  ui_story_5061_50610402_50_dialog_content = "S-Claro que sí!",
  ui_story_5061_50610402_51_dialog_content = "Cuando llegamos aquí, PlayerName me preguntó... Si había alguna emergencia reportada en esta área.",
  ui_story_5061_50610402_52_dialog_content = "Le dije que esta área ha estado en paz durante bastante tiempo, ya que los Eclipsites solo existen fuera de las fronteras de Northland. Además, todos los equipos de patrulla han informado al palacio sin incidentes.",
  ui_story_5061_50610402_53_dialog_content = "Lo más cercano que he escuchado sobre patrulleros desaparecidos es cuando alguno de nosotros se aleja un poco más de lo habitual. Cuando eso sucede, simplemente perdemos contacto por un tiempo. Las batallas casi nunca ocurren y las muertes son aún menos comunes...",
  ui_story_5061_50610402_54_dialog_content = "Además de los rumores de que algunas personas escuchan el \"Espíritu de la Aurora\" en lo profundo de las montañas, no se ha informado de ninguna actividad inusual en esta área.",
  ui_story_5061_50610402_55_dialog_content = "En otras palabras, a pesar de nuestros mejores esfuerzos para recopilar información, no hemos aprendido nada relacionado con tu hermana o los patrulleros desaparecidos.",
  ui_story_5061_50610402_56_dialog_content = "Esto significa que si lo que nos dices es verdad, tu hermana debería estar en casa sana y salva.",
  ui_story_5061_50610402_57_dialog_content = "¿En serio? Me sentiría tan aliviado si eso fuera cierto...",
  ui_story_5061_50610402_58_dialog_content = "Es posible que la respuesta esté en algún lugar de tu mente, Zarya.",
  ui_story_5061_50610402_59_dialog_content = "¿Eh? ¿Q-Qué quieres decir?",
  ui_story_5061_50610402_60_dialog_content = "Después de combinar las observaciones de Antony y mis propios descubrimientos...",
  ui_story_5061_50610402_61_dialog_content = "Mi suposición es que pasaste demasiado tiempo atrapado en un ambiente lleno de un tipo extraño de Lumina. Como resultado, tus recuerdos se mezclaron un poco.",
  ui_story_5061_50610402_62_dialog_content = "Por eso sigues confundiendo eventos pasados con nuestra realidad actual.",
  ui_story_5061_50610402_63_dialog_content = "M-Mis recuerdos están \"revueltos\"?",
  ui_story_5061_50610402_64_dialog_content = "De cierta manera, sí. Supongo que una mejor forma de decirlo es que algún tipo de energía ha afectado tu cerebro, dificultando entender lo que está pasando a tu alrededor.",
  ui_story_5061_50610402_65_dialog_content = "Entonces, ¿en otras palabras, me he vuelto más tonto?!",
  ui_story_5061_50610402_66_dialog_content = "Supongo que tienes razón... Después de todo, en lugar de rescatar a mi hermana, terminé atrapándome en el hielo...",
  ui_story_5061_50610402_67_dialog_content = "Soy completamente inútil... No creo que haya un tonto más grande en el mundo que yo mismo.",
  ui_story_5061_50610402_68_dialog_content = "Vamos Zarya, ¡no digas eso! ¡Mira tus Luminatics de antes! No creo que alguien inútil pueda hacer algo así.",
  ui_story_5061_50610402_69_dialog_content = "En un abrir y cerrar de ojos, me salvaste de una muerte segura ¡Y eliminaste a todos los Eclipsites a nuestro alrededor!",
  ui_story_5061_50610402_70_dialog_content = "La Lumina de tu ataque era bonita. Se parecía mucho a tu cabello...",
  ui_story_5061_50610402_71_dialog_content = "Cuando Leah te vio por primera vez, ¡honestamente pensó que eras el Espíritu de la Aurora!",
  ui_story_5061_50610402_72_dialog_content = "¡Es cierto! La forma en que tu cabello brilla y resplandece... ¡Es como si la Aurora lo bendijera!",
  ui_story_5061_50610402_73_dialog_content = "... ¿Brillos? ¿Qué brillos?",
  ui_story_5061_50610402_74_dialog_content = "Oh, eh... Es un poco incómodo admitirlo, pero estaba tan fascinado por el cabello de la señorita Zarya, ya que el mío es tan corto...",
  ui_story_5061_50610402_75_dialog_content = "Así que la ayudé a cepillarlo mientras dormía. Fue entonces cuando descubrí...",
  ui_story_5061_50610402_76_dialog_content = "Su cabello emite un suave resplandor, ¡como un antiguo relicario mágico del pasado! Ya sabes, ¡como en las historias!",
  ui_story_5061_50610402_77_dialog_content = "¡¿M-Mi cabello?! Pero... Pero esto no es... ¡Mi cabello no siempre fue de este color!",
  ui_story_5061_50610402_78_dialog_content = "Ella tiene razón, tu cabello está emitiendo Lumina. ¡Esto debe ser un efecto secundario de estar atrapado dentro de tus Lumináticas durante tanto tiempo!",
  ui_story_5061_50610402_79_dialog_content = "¡Eres como una fuente ambulante de Lumina, liberándola constantemente en el espacio a tu alrededor!",
  ui_story_5061_50610402_80_dialog_content = "Esto debe ser de lo que Antony hablaba antes... ¿Tal vez deberíamos ir a preguntarle más al respecto?",
  ui_story_5061_50610402_81_dialog_content = "¿Tienes alguna forma de contactarlo, Leah?",
  ui_story_5061_50610402_82_dialog_content = "¡Sí, de hecho! Ven conmigo y te llevaré al pueblo donde él suele realizar sus investigaciones.",
  ui_story_5061_50610402_83_dialog_content = "Si tuviera que adivinar, probablemente esté ahí ahora mismo.",
  ui_story_5061_50610501_1_dialog_content = "¡Mira quién está aquí! Leah, nuestro Elfo de Primavera!",
  ui_story_5061_50610501_2_dialog_content = "¿Patrullando en la carretera de montaña otra vez hoy?",
  ui_story_5061_50610501_3_dialog_content = "E-Eso es correcto... Pero hoy no estoy en mi ruta de patrulla habitual.",
  ui_story_5061_50610501_4_dialog_content = "Tengo... algunos asuntos personales que atender.",
  ui_story_5061_50610501_5_dialog_content = "¿Estos dos son tus amigos, Leah?",
  ui_story_5061_50610501_6_dialog_content = "Vaya, esto es inesperado. Forasteros apareciendo en esta zona remota. Y tú, joven, no pareces ser de Northland.",
  ui_story_5061_50610501_7_dialog_content = "¿Eh? ¿Te refieres a mí?",
  ui_story_5061_50610501_8_dialog_content = "Absolutamente. El tiempo ha pasado volando y ahora tenemos turistas por aquí. En aquellos días, este era en realidad el frente de batalla contra la invasión de los Eclipsites...",
  ui_story_5061_50610501_9_dialog_content = "La carretera de montaña estaba completamente cubierta de nieve y bloqueada. Nosotros, los lugareños, solo podíamos seguir de cerca a las patrullas...",
  ui_story_5061_50610501_10_dialog_content = "Perdón, pero ¿a qué equipo de patrulla se refiere?",
  ui_story_5061_50610501_11_dialog_content = "No creo que esté hablando de tu hermana, señorita Zarya. Si acaso... Se refiere a mis padres.",
  ui_story_5061_50610501_12_dialog_content = "¿Eh? ¿Tus padres también eran patrulleros de Northland, Leah?",
  ui_story_5061_50610501_13_dialog_content = "Sí, pero... Fallecieron hace mucho tiempo.",
  ui_story_5061_50610501_14_dialog_content = "Oh, lo siento. No quise mencionar un tema tan delicado.",
  ui_story_5061_50610501_15_dialog_content = "¿No saben ustedes que Leah es un huérfano de las patrullas?",
  ui_story_5061_50610501_16_dialog_content = "La verdad es que, aunque los Eclipsites no están invadiendo aquí como lo hacían hace años, este trabajo sigue siendo bastante arriesgado.",
  ui_story_5061_50610501_17_dialog_content = "Este no es un lugar como el Palacio de Invierno o el Lago Espejo, vigilado por Su Majestad la Queen y Lady Nikinis...",
  ui_story_5061_50610501_18_dialog_content = "Solo podemos confiar en los miembros de las patrullas. Pero la idea de que niños como Leah tengan que manejar todo esto es un poco difícil de ver.",
  ui_story_5061_50610501_19_dialog_content = "Realmente... ¡No es ningún problema en absoluto! Su Majestad me confió el Bastón de Primavera y tengo tantos amigos ayudándome...",
  ui_story_5061_50610501_20_dialog_content = "Manejar algunos Eclipsites no es un problema en absoluto... Además, también tengo vacaciones pagadas, lo cual es aún mejor...",
  ui_story_5061_50610501_21_dialog_content = "Suspiro. No importa qué, estas cosas aún necesitan que alguien las maneje. Y no estoy exactamente en posición de darte más consuelo.",
  ui_story_5061_50610501_22_dialog_content = "Todo lo que podemos hacer es agradecerte por tu dedicación.",
  ui_story_5061_50610501_23_dialog_content = "Un trabajo que necesita hacerse...",
  ui_story_5061_50610501_24_dialog_content = "Sabes, he notado que a veces te ves un poco solo.",
  ui_story_5061_50610501_25_dialog_content = "No elegiste este trabajo solo para ser patrullero, ¿verdad? Si acaso, probablemente querías sentirte más cerca de tus padres siguiendo sus pasos...",
  ui_story_5061_50610501_26_dialog_content = "¿Verdad?",
  ui_story_5061_50610501_27_dialog_content = "Ah... Viste a través de mí...",
  ui_story_5061_50610501_28_dialog_content = "Eso es porque a veces me siento exactamente igual.",
  ui_story_5061_50610501_29_dialog_content = "¿En serio? ¿Tú también sientes lo mismo?",
  ui_story_5061_50610501_30_dialog_content = "Para ser honesto, realmente no sabía en qué estaba pensando cuando acepté el Bastón de Primavera y me convertí en un patrullero...",
  ui_story_5061_50610501_31_dialog_content = "Tal vez fue para acercarme a mis padres... O tal vez estaba tan impresionado por Su Majestad que quería luchar a su lado...",
  ui_story_5061_50610501_32_dialog_content = "Pero tomar el Bastón de Primavera... ¡Esa decisión la tomé completamente por mi cuenta!",
  ui_story_5061_50610501_33_dialog_content = "¡Y quería darle sentido a esa elección! Por eso... Por eso decidí seguir siendo un patrullero.",
  ui_story_5061_50610501_34_dialog_content = "Esa es una realización increíble, Leah.",
  ui_story_5061_50610501_35_dialog_content = "La decisión de perseverar en el camino que has elegido...",
  ui_story_5061_50610501_36_dialog_content = "Hola, pequeño Leah! ¿Puedes ayudarme a averiguar adónde se fueron esos dos niños de al lado?",
  ui_story_5061_50610501_37_dialog_content = "Solo prometí a sus padres que los vigilaría por un rato, pero ¡puf! desaparecieron en un abrir y cerrar de ojos.",
  ui_story_5061_50610501_38_dialog_content = "¡Oh, claro! De hecho... creo que sé exactamente dónde buscarlos.",
  ui_story_5061_50610501_39_dialog_content = "Pero antes de eso, quisiera preguntar... ¿Has visto al Sr. Antony?",
  ui_story_5061_50610501_40_dialog_content = "¿De quién estás hablando? ¿Es de nuestro pueblo?",
  ui_story_5061_50610501_41_dialog_content = "Eh, no realmente. El Sr. Antony es un erudito de buen corazón que se mudó aquí recientemente. A menudo lee a los niños y les enseña sobre las estrellas y cómo usarlas para navegar.",
  ui_story_5061_50610501_42_dialog_content = "Oh, sí. Refrescaste mi memoria: alguien así vivía cerca del pueblo.",
  ui_story_5061_50610501_43_dialog_content = "Los niños dicen que siempre está jugando con algún dispositivo extraño, pero es lo suficientemente amable.",
  ui_story_5061_50610501_44_dialog_content = "Entonces, ¿dices que es un erudito? No me lo imagino. ¿No deberían los eruditos estar encerrados en casa leyendo libros todo el día?",
  ui_story_5061_50610501_45_dialog_content = "Pero este tipo, siempre está usando ese cuerpo musculoso suyo, corriendo por las montañas y regresando todo golpeado y magullado.",
  ui_story_5061_50610501_46_dialog_content = "Entonces, ¿qué estudia exactamente?",
  ui_story_5061_50610501_47_dialog_content = "Él está, eh, investigando los orígenes de los Aurorianos, como de dónde venimos y hacia dónde vamos. Ya sabes, ese tipo de cosas.",
  ui_story_5061_50610501_48_dialog_content = "Bueno, eso es bastante extraño. Correr como loco en las montañas todos los días, ¿realmente eso le ayuda a descubrir todas estas cosas?",
  ui_story_5061_50610501_49_dialog_content = "¿Por qué no estudia qué está causando que los cultivos aquí se marchiten? No había muchas alternativas que pudieran crecer en este lugar frío para empezar.",
  ui_story_5061_50610501_50_dialog_content = "No puedo decirle realmente qué hacer, lo siento. Además, no todo tiene su respuesta.",
  ui_story_5061_50610501_51_dialog_content = "Pero aún así, el Sr. Antony podría haber investigado algo relacionado con eso...",
  ui_story_5061_50610501_52_dialog_content = "Una vez me dijo... Que \"primavera\" significa dos cosas diferentes para los cultivos y los Aurorianos.",
  ui_story_5061_50610501_53_dialog_content = "¿Dos primaveras diferentes? ¿Qué podría significar eso?",
  ui_story_5061_50610501_54_dialog_content = "Supongo que simplemente tendremos que preguntarle sobre eso cuando lo encontremos.",
  ui_story_5061_50610501_55_dialog_content = "De todos modos, tengo que ir a verlo.",
  ui_story_5061_50610501_56_dialog_content = "Igual aquí. Esos dos niños disfrutan haciéndole muchas preguntas al Sr. Antony, igual que yo...",
  ui_story_5061_50610501_57_dialog_content = "Probablemente estén aprendiendo algo nuevo en su casa si no están en el pueblo en este momento.",
  ui_story_5061_50610502_1_dialog_content = "Uf... Finalmente estamos aquí.",
  ui_story_5061_50610502_2_dialog_content = "Dijiste que su casa está en el camino hacia Cedar Peak, pero prácticamente vive al pie de la montaña.",
  ui_story_5061_50610502_3_dialog_content = "Bueno, él vino aquí para investigar la montaña...",
  ui_story_5061_50610502_4_dialog_content = "Hay tantos libros aquí... Y mira, una radio.",
  ui_story_5061_50610502_5_dialog_content = "Tiene más libros que una biblioteca... Espera, ¿qué es un \"ready-o\"?",
  ui_story_5061_50610502_6_dialog_content = "Se pronuncia \"radio\", señorita Zarya. Según tengo entendido, la mayoría de los forasteros las compran en Umbraton...",
  ui_story_5061_50610502_7_dialog_content = "¿Son estas... las notas del Sr. Antony?",
  ui_story_5061_50610502_8_dialog_content = "Déjame ver si hay alguna pista en ello...",
  ui_story_5061_50610502_9_dialog_content = "Miraré alrededor también... ¡Vaya, él realmente ha investigado el problema del mal crecimiento de los cultivos locales!",
  ui_story_5061_50610502_10_dialog_content = "\"Año tras año, los campos alrededor de Cedar Village no logran producir cultivos saludables, y la situación parece empeorar con cada año que pasa. Sospecho que la Lumina anormal en la zona es la responsable.\"",
  ui_story_5061_50610502_11_dialog_content = "... La letra del Sr. Antony es linda, ¿no crees? ¡Se parece a la letra de un niño!",
  ui_story_5061_50610502_12_dialog_content = "(Bueno, eso tiene sentido, considerando que su única educación formal fue cuando era niño...)",
  ui_story_5061_50610502_13_dialog_content = "También tiene algunos esquemas dibujados a mano aquí. ¿Un \"bastón de trekking multifuncional\"? Vaya, no tenía idea de que el Sr. Antony diseñó y construyó ese bastón para caminar que siempre lleva consigo.",
  ui_story_5061_50610502_14_dialog_content = "Parece que también ha pasado por un par de versiones. Según sus notas, se rompía constantemente durante las peleas con Eclipsites...",
  ui_story_5061_50610502_15_dialog_content = "Entonces, se enfocó en fortalecer su diseño en las siguientes versiones... ¡Eso apenas suena \"multifuncional\" para mí!",
  ui_story_5061_50610502_16_dialog_content = "Soy muy consciente de eso. Como un semi-humano, soy más que capaz de defenderme por mí mismo. Además, ¡he estado en este tipo de situación innumerables veces antes!",
  ui_story_5061_50610502_17_dialog_content = "Al menos, debería poder sobrevivir a sus ataques hasta que se cansen.",
  ui_story_5061_50610502_18_dialog_content = "Aunque cuando se trata de él... La resistencia es probablemente la función más útil que algo podría tener.",
  ui_story_5061_50610502_19_dialog_content = "PlayerName? También menciona algo llamado \"función de transmisor\". ¿Qué significa eso?",
  ui_story_5061_50610502_20_dialog_content = "<size=45>¡Cuidado! ¡Eclipsites!</size>",
  ui_story_5061_50610502_21_dialog_content = "¿Eclipsitos?! ¡¿Dónde?!?",
  ui_story_5061_50610502_22_dialog_content = "¡Jajaja, te atrapé! ¡Eres un gallina!",
  ui_story_5061_50610502_23_dialog_content = "¡Ahí están, ustedes dos! ¡Su familia ha estado muy preocupada! ¿No podrían al menos decirles a dónde van antes de desaparecer del pueblo?",
  ui_story_5061_50610502_24_dialog_content = "¡Ella tiene razón, sabes! ¡Tampoco es agradable jugar bromas así!",
  ui_story_5061_50610502_25_dialog_content = "¡Los niños que lloran Eclipsites para llamar la atención suelen ser los primeros en ser devorados!",
  ui_story_5061_50610502_26_dialog_content = "Vaya, ¿por qué hablas como mi abuela? ¡Nadie asusta a los niños así en estos días!",
  ui_story_5061_50610502_27_dialog_content = "Además, conocemos esta área como la palma de nuestras manos. Sabemos perfectamente dónde es riesgoso y dónde es seguro.",
  ui_story_5061_50610502_28_dialog_content = "Si no nos crees, podemos mostrarte nuestro movimiento especial: ¡<color=#FFB400>Pesca de Eclipsite</color>!",
  ui_story_5061_50610502_29_dialog_content = "¿Quieres verlo? Atraemos a los Eclipsites para que nos persigan, luego los llevamos al resplandor del faro. ¡Y bam! ¡Los Eclipsites están fritos!",
  ui_story_5061_50610502_30_dialog_content = "Y algunos Eclipsites finalmente se dan cuenta de lo que está pasando y salen corriendo como gallinas, no puedo describir lo gracioso que es, ¡jajaja!",
  ui_story_5061_50610502_31_dialog_content = "¿Están locos, niños?! ¡Eso es demasiado peligroso!",
  ui_story_5061_50610502_32_dialog_content = "Estos niños realmente no entienden lo bendecidos que son al vivir en paz...",
  ui_story_5061_50610502_33_dialog_content = "Porque es tan aburrido aquí, ya sabes. No hay muchas cosas emocionantes en la frontera.",
  ui_story_5061_50610502_34_dialog_content = "Excepto por lo que dijo el Sr. Antony. Eso es bastante fascinante.",
  ui_story_5061_50610502_35_dialog_content = "¿Que dijo el?",
  ui_story_5061_50610502_36_dialog_content = "El Sr. Antony dijo que las cosas en los cuentos de hadas eran reales.",
  ui_story_5061_50610502_37_dialog_content = "¿Recuerdas ese viejo cuento de hadas? El que habla de que Northland alguna vez fue un lugar exuberante, verde y lleno de vida?",
  ui_story_5061_50610502_38_dialog_content = "Tengo la sensación de que esto no es solo un cuento de hadas, ¡sino una historia real del pasado!",
  ui_story_5061_50610502_39_dialog_content = "¿De verdad?",
  ui_story_5061_50610502_40_dialog_content = "¡Encontré algo que también podría demostrarlo! Los anillos de un árbol antiguo encontrado congelado en hielo durante incontables siglos...",
  ui_story_5061_50610502_41_dialog_content = "¡Sabes, los cambios en el clima de un área se pueden ver en los anillos de los árboles!",
  ui_story_5061_50610502_42_dialog_content = "Las secciones más dispersas de los anillos de los árboles indican un ambiente de crecimiento relativamente más cálido en ese momento, mientras que las partes más densas indican lo contrario. En cuanto al árbol que encontré, los anillos más internos son excepcionalmente dispersos.",
  ui_story_5061_50610502_43_dialog_content = "¡Lo que significa que en algún momento, Northland fue un lugar cálido! ¡Incluso podría haber experimentado una verdadera temporada de primavera!",
  ui_story_5061_50610502_44_dialog_content = "¡Eso significa que los cuentos de hadas son reales, no solo algo inventado para engañar a los niños! ¡Voy a contarle esto a la abuela!",
  ui_story_5061_50610502_45_dialog_content = "Pero de nuevo, ¿por qué hace tanto frío en Northland ahora?",
  ui_story_5061_50610502_46_dialog_content = "Bueno, Northland se encuentra a una altitud muy alta. También está muy cerca de la Tierra de la Noche Eterna, que estoy seguro de que también es un lugar extremadamente frío.",
  ui_story_5061_50610502_47_dialog_content = "De hecho, si Northland solía ser un lugar cálido... Entonces eso significa que el Círculo Crepuscular que todos conocemos no estaba aquí...",
  ui_story_5061_50610502_48_dialog_content = "¿Cómo era exactamente el mundo hace tantos años...?",
  ui_story_5061_50610502_49_dialog_content = "Señor Antony, ¿Señor Antony?",
  ui_story_5061_50610502_50_dialog_content = "Tu voz se volvió baja y lo que decías era demasiado oscuro. No podemos entenderlo.",
  ui_story_5061_50610502_51_dialog_content = "Lo siento, niños. El mundo está tan lleno de misterios sin resolver que incluso yo tengo dificultades para entender las cosas.",
  ui_story_5061_50610502_52_dialog_content = "Por eso es mejor no molestar a otras personas con este tipo de cosas, ¿de acuerdo?",
  ui_story_5061_50610502_53_dialog_content = "¡Me encantan los misterios sin resolver! ¿Sabes qué pasa con la superficie del Lago Espejo, el resplandor del Faro y el hielo eterno de Queen?",
  ui_story_5061_50610502_54_dialog_content = "¡Jajaja! Aunque sería bastante descortés preguntar sobre los secretos de Su Majestad, con suficiente estudio y comunicación...",
  ui_story_5061_50610502_55_dialog_content = "Es posible que lo sepamos algún día.",
  ui_story_5061_50610502_56_dialog_content = "¡Quiero estudiar contigo! También tengo curiosidad por saber si el Espíritu de Aurora es real.",
  ui_story_5061_50610502_57_dialog_content = "Eres más que bienvenido a unirte a mí algún día, pero ten cuidado: esta línea de trabajo está llena de peligros y dificultades. Necesitarás entrenar tanto tu mente como tu cuerpo si quieres seguir el ritmo.",
  ui_story_5061_50610502_58_dialog_content = "Bueno, pequeños, ¿creen que estas bromas suyas cuentan como entrenamiento?",
  ui_story_5061_50610502_59_dialog_content = "Estoy seguro de que el Sr. Antony te enseñó mejor, ¿verdad?",
  ui_story_5061_50610502_60_dialog_content = "Lo siento...",
  ui_story_5061_50610502_61_dialog_content = "... El Sr. Antony dijo que no deberíamos meternos con los Eclipsites y que deberíamos valorar el poder del Faro porque Queen ha estado haciendo un gran esfuerzo para mantenerlo.",
  ui_story_5061_50610502_62_dialog_content = "...Entonces, no hemos jugado al juego de pescar Eclipsites desde ese entonces. Solo estábamos presumiendo ante ti hace un momento...",
  ui_story_5061_50610502_63_dialog_content = "Me alegra que entiendas. Haces que todos se preocupen por ti incluso cuando solo estás presumiendo, ¿sabes?",
  ui_story_5061_50610502_64_dialog_content = "Hmm... Lo siento.",
  ui_story_5061_50610502_65_dialog_content = "Señorita Zarya... ¡Eso fue increíble! S-supongo que no soy muy bueno en tener conversaciones difíciles con los demás...",
  ui_story_5061_50610502_66_dialog_content = "Honestamente, estaba fingiendo ser otra persona justo ahora. También me sorprende que haya funcionado tan bien...",
  ui_story_5061_50610502_67_dialog_content = "P-Para decir la verdad, me gustaría aprender a ser más compasivo como Leah...",
  ui_story_5061_50610502_68_dialog_content = "Sabes, eras bastante compasivo cuando estabas dormido.",
  ui_story_5061_50610502_69_dialog_content = "No recuerdo haberte preguntado—",
  ui_story_5061_50610502_70_dialog_content = "¿Qué ha estado haciendo el Sr. Antony últimamente? Ha pasado un tiempo desde la última vez que nos contó historias...",
  ui_story_5061_50610502_71_dialog_content = "Me hace preocuparme un poco...",
  ui_story_5061_50610502_72_dialog_content = "Debe estar investigando lo que está escrito aquí en estas notas: la Tormenta de Aurora, la extraña Lumina y la cueva congelada en el Pico de Cedro.",
  ui_story_5061_50610502_73_dialog_content = "Dice aquí que un gran conjunto de ruinas no identificadas podría existir en algún lugar dentro de Cedar Peak...",
  ui_story_5061_50610502_74_dialog_content = "... ¿Podría ser esa la fuente de la extraña Lumina que sentí antes?",
  ui_story_5061_50610502_75_dialog_content = "(Entonces, ¿cómo está Zarya conectado a todo esto?)",
  ui_story_5061_50610502_76_dialog_content = "La Auroratormenta... y el Pico de Cedro...",
  ui_story_5061_50610502_77_dialog_content = "¿Qué estaba haciendo antes de que me congelaran? Urgh—",
  ui_story_5061_50610502_78_dialog_content = "(¡No quiero quedarme en la oscuridad para siempre! Quiero saber... ¡quiero recordar qué me pasó!)",
  ui_story_5061_50610601_1_dialog_content = "No pensé que nuestra búsqueda nos llevaría de vuelta al lugar donde te encontramos, Zarya.",
  ui_story_5061_50610601_2_dialog_content = "¿Te sientes bien?",
  ui_story_5061_50610601_3_dialog_content = "¡Estoy bien! Además, ¡no iba a dejarte volver a la montaña por tu cuenta!",
  ui_story_5061_50610601_4_dialog_content = "Realmente no deberías esforzarte tanto. Podría haber esperado a que Leah regresara y me acompañara aquí.",
  ui_story_5061_50610601_5_dialog_content = "¡Como dije! Estoy bien, ¡así que no te preocupes por eso!",
  ui_story_5061_50610601_6_dialog_content = "Todos están trabajando tan duro para ayudarme en este momento... ¿Qué clase de persona sería si te dejara enfrentarte al frío y a los Eclipsites tú solo...",
  ui_story_5061_50610601_7_dialog_content = "Simplemente busco respuestas. En ese aspecto, no soy diferente a Leah o Antony...",
  ui_story_5061_50610601_8_dialog_content = "Quiero enfrentar mi pasado y asumir la responsabilidad de lo que he hecho, sin importar cuán tonto haya sido. Me niego a fingir que nunca pasó nada.",
  ui_story_5061_50610601_9_dialog_content = "Bueno, siempre es bueno tener una meta en mente.",
  ui_story_5061_50610601_10_dialog_content = "Pero... ¿No crees que deberías estar preparándote para ir a casa ahora mismo, en lugar de eso? ¿O tal vez buscando algo para cambiar el color de tu cabello?",
  ui_story_5061_50610601_11_dialog_content = "... Ya he escrito una carta a casa diciendo que estoy a salvo. Sin embargo, el mensajero necesita un poco más de tiempo para llegar aquí.",
  ui_story_5061_50610601_12_dialog_content = "(Espero que la dirección que recuerdo siga siendo correcta...)",
  ui_story_5061_50610601_13_dialog_content = "Por eso... necesito algo que hacer mientras tanto.",
  ui_story_5061_50610601_14_dialog_content = "Incluso si mi hermana está a salvo, no puedo volver a casa hasta que entienda por qué perdí el control de mis poderes de esa manera.",
  ui_story_5061_50610601_15_dialog_content = "Solo... Realmente necesito volver y descubrir qué demonios me pasó a mí!",
  ui_story_5061_50610601_16_dialog_content = "Qué hermoso...",
  ui_story_5061_50610601_17_dialog_content = "Eh...? ¿De qué estás hablando?!",
  ui_story_5061_50610601_18_dialog_content = "¡Estoy hablando del cielo! Supongo que no lo noté realmente cuando te estábamos rescatando antes.",
  ui_story_5061_50610601_19_dialog_content = "Escuché a alguien decir que el borde del Círculo Crepúsculo no estaba muy lejos de aquí en nuestro camino de regreso por la montaña.",
  ui_story_5061_50610601_20_dialog_content = "O-Oh, así que eso es lo que querías decir... Esto es bastante común para aquellos de nosotros que crecimos en las zonas fronterizas.",
  ui_story_5061_50610601_21_dialog_content = "Antes de hoy, solo había leído sobre ello en las bases de datos de Soroz. No es de extrañar que Antony estuviera tan interesado en enseñarles a esos niños al respecto.",
  ui_story_5061_50610601_22_dialog_content = "No muchas personas dedican tanto tiempo o esfuerzo en entenderlo. Creo que el Sr. Antony es la persona más apasionada que he conocido en este aspecto.",
  ui_story_5061_50610601_23_dialog_content = "De la misma manera, pocas personas buscan comprender la fuente del poder del Faro o las razones del Queen para proteger Northland.",
  ui_story_5061_50610601_24_dialog_content = "Vivir una vida sencilla debe ser bastante agradable. Las opiniones de todos aquí son tan puras y sin complicaciones.",
  ui_story_5061_50610601_25_dialog_content = "Tal vez tenga que ver con lo desconectado que está Northland de las luchas del resto del mundo. Ha sido exactamente igual durante incontables años.",
  ui_story_5061_50610601_26_dialog_content = "En realidad, Northland es bastante diferente de lo que aún puedo recordar. La diferencia más obvia es lo fácil que un forastero como tú podría aparecer en este lugar.",
  ui_story_5061_50610601_27_dialog_content = "Supongo que Northland y los Caelestites tienen algo en común, ¿verdad? Ambos nos aislamos del mundo para mantener nuestra neutralidad.",
  ui_story_5061_50610601_28_dialog_content = "¿Los Caelestites tienen muy poco contacto con el mundo exterior?",
  ui_story_5061_50610601_29_dialog_content = "Sí. Para evitar conflictos con el resto del mundo y vivir en paz, mi gente decidió aislarse en Eraveil, un lugar donde apenas pisan los forasteros.",
  ui_story_5061_50610601_30_dialog_content = "Desde pequeños, nos enseñan a nunca salir o interactuar con el mundo exterior sin el permiso de nuestros mayores.",
  ui_story_5061_50610601_31_dialog_content = "Entonces, ¿qué te hizo salir de Eraveil?",
  ui_story_5061_50610601_32_dialog_content = "Lamentablemente, todos nuestros esfuerzos por mantenernos alejados del resto del mundo no nos mantuvieron a salvo de los Eclipsites.",
  ui_story_5061_50610601_33_dialog_content = "Hace muchos años, una legión de Eclipsites descendió sobre Eraveil, aniquilando a cada uno de mi pueblo. Yo fui el único superviviente.",
  ui_story_5061_50610601_34_dialog_content = "¿¡Qué?! Entonces, así de simple, los legendarios Celestitas... ¿Ya no existen?",
  ui_story_5061_50610601_35_dialog_content = "... Lo siento mucho. No quise traer recuerdos tan dolorosos. Debes sentirte muy solo.",
  ui_story_5061_50610601_36_dialog_content = "Jaja, ¡no hay nada por lo que disculparse! Por terrible que sea, ya he aceptado el pasado.",
  ui_story_5061_50610601_37_dialog_content = "Siento que puedo entender cómo te sientes. Aunque mis experiencias de vida no son nada comparadas con las tuyas.",
  ui_story_5061_50610601_38_dialog_content = "Cuando era pequeño, causé muchos problemas a mi familia porque no podía controlar mis Luminatics.",
  ui_story_5061_50610601_39_dialog_content = "Mi padre estaba especialmente avergonzado de mí. Siempre estaba tan distante y me mantenía encerrado en casa por miedo a que dañara su negocio.",
  ui_story_5061_50610601_40_dialog_content = "Eventualmente, perdí casi todas mis habilidades sociales. No tenía amigos ni siquiera el valor para hacer amigos.",
  ui_story_5061_50610601_41_dialog_content = "Cuando lo pienso, mi vida realmente no era diferente a cuando estaba atrapado en el hielo.",
  ui_story_5061_50610601_42_dialog_content = "Debes haber sufrido la misma soledad... Atrapado completamente solo, sin nadie para acompañarte.",
  ui_story_5061_50610601_43_dialog_content = "Al principio, sí. Pasé casi toda mi infancia atrapado en un espacio pequeño. Si quería aprender algo sobre el mundo exterior, tenía que depender de las bases de datos de Soroz.",
  ui_story_5061_50610601_44_dialog_content = "Con el tiempo, comencé a preguntarme si realmente existía en el mundo.",
  ui_story_5061_50610601_45_dialog_content = "Y ahora, aunque puedo ver el mundo con mis propios dos ojos... Esa misma sensación aún me encuentra de vez en cuando.",
  ui_story_5061_50610601_46_dialog_content = "Por eso elijo seguir avanzando, pase lo que pase. Si no sigo avanzando, nada cambiará nunca.",
  ui_story_5061_50610601_47_dialog_content = "Mi gente alguna vez vivió en este mundo e incluso luchó para protegerlo. Voy a hacer lo mismo.",
  ui_story_5061_50610601_48_dialog_content = "... Sabes, hablar contigo se siente como hablar con mi hermana. Ambas son tan fuertes pero a la vez tan bondadosas.",
  ui_story_5061_50610601_49_dialog_content = "A diferencia de mí, que siempre hago enojar a los demás con mi terrible toma de decisiones...",
  ui_story_5061_50610601_50_dialog_content = "Si fuera más como tú, tal vez Papá no me habría dado la espalda. Quizás habría rescatado a mi hermana...",
  ui_story_5061_50610601_51_dialog_content = "En lugar de terminar atrapado en el hielo.",
  ui_story_5061_50610601_52_dialog_content = "Acabo de recordar, los Celestitas se supone que tienen poderes psíquicos legendarios, ¿verdad? ¿También usaste esos poderes para despertarme?",
  ui_story_5061_50610601_53_dialog_content = "Así es. De hecho, estoy pensando en usarlos de nuevo ahora mismo.",
  ui_story_5061_50610601_54_dialog_content = "Sabes, parece que estás bastante desinformado sobre la historia reciente de Astra.",
  ui_story_5061_50610601_55_dialog_content = "De hecho, se siente como si estuvieras atrapado en el hielo durante mucho tiempo.",
  ui_story_5061_50610601_56_dialog_content = "¡O-Oye! ¡Eres tú quien me presenta todo tipo de nueva información! ¡Por supuesto que te vas a sentir así!",
  ui_story_5061_50610601_57_dialog_content = "¡Shhh! ¡Siento Eclipsites!",
  ui_story_5061_50610601_58_dialog_content = "Parece que estamos bastante fuera de la barrera invisible de Queen Bethlehem.",
  ui_story_5061_50610602_1_dialog_content = "¡Teñiré la nieve con vuestra sangre, monstruos!",
  ui_story_5061_50610602_2_dialog_content = "Gruñido...",
  ui_story_5061_50610602_3_dialog_content = "¡Apenas fue un desafío!",
  ui_story_5061_50610602_4_dialog_content = "Es extraño... Algo no está bien con estos Eclipsites.",
  ui_story_5061_50610602_5_dialog_content = "¿Qué quieres decir?",
  ui_story_5061_50610602_6_dialog_content = "Están intentando alejarse de ti. ¿Podría ser que pueden sentir tus niveles anormalmente altos de Lumina?",
  ui_story_5061_50610602_7_dialog_content = "Hmph, eso me funciona bien. Si esta extraña Lumina es tan aterradora, podría simplemente mantenerla dentro de mí.",
  ui_story_5061_50610602_8_dialog_content = "Aparte de cambiar el color de mi cabello al mismo color que la aurora, no parece afectarme de ninguna otra manera...",
  ui_story_5061_50610602_9_dialog_content = "Haré todo lo posible para controlarlo y no congelar tus piernas de nuevo.",
  ui_story_5061_50610602_10_dialog_content = "Entonces, ¿todavía recuerdas que me quejé de eso, eh?",
  ui_story_5061_50610602_11_dialog_content = "Mientras evites mi cabeza, deberíamos estar bien. No quiero terminar congelado Y con el cabello de otro color.",
  ui_story_5061_50610602_12_dialog_content = "No tienes que sonar tan asustado, ¡ya sabes!",
  ui_story_5061_50610602_13_dialog_content = "Solo estoy un poco nervioso al verte tan familiarizado con tus ataques. Solo van a volverse más fuertes de aquí en adelante...",
  ui_story_5061_50610602_14_dialog_content = "¿De verdad crees que podría perder el control tan mal?!",
  ui_story_5061_50610602_15_dialog_content = "No es del todo descabellado, ¿verdad? Después de todo, terminaste congelándote a ti mismo junto con la mitad del Pico Cedar.",
  ui_story_5061_50610602_16_dialog_content = "Dijiste que querías enfrentarte a tu pasado sin importar lo malo que sea, ¿verdad? ¿O estás intentando echar la culpa de nuevo al Espíritu de la Aurora?",
  ui_story_5061_50610602_17_dialog_content = "Yo...",
  ui_story_5061_50610602_18_dialog_content = "Gaah—Graaah...",
  ui_story_5061_50610602_19_dialog_content = "Está bien, admito que tal vez me emocioné un poco demasiado cuando sentí ese poder dentro de mí...",
  ui_story_5061_50610602_20_dialog_content = "Bien. Me alegra que sintamos lo mismo.",
  ui_story_5061_50610602_21_dialog_content = "Hablando de emoción, el Sr. Antony realmente está dedicado a su investigación, ¿verdad? ¿Crees que la Aurora también está conectada a una fuente de energía antigua?",
  ui_story_5061_50610602_22_dialog_content = "Mi hermana y yo presenciamos la Aurora tormentosa por nosotros mismos... ¿Podría haberse originado también en las ruinas cercanas?",
  ui_story_5061_50610602_23_dialog_content = "Probablemente no lo sabremos hasta que le preguntemos a Antony mismo...",
  ui_story_5061_50610602_24_dialog_content = "Pero si tuviera que adivinar, esta extraña Lumina probablemente sea la razón por la que tienes el poder de congelar montañas enteras.",
  ui_story_5061_50610602_25_dialog_content = "Y por lo que puedo percibir, esta extraña Lumina proviene de algún lugar bajo tierra. Puede estar conectada a la misma fuente de Lumina que produjo la Auroratormenta.",
  ui_story_5061_50610602_26_dialog_content = "Antony dice que parte del problema es la falta de registros recientes sobre Aurorastorm... Lo que significa que no sabemos cuánto tiempo atrás ocurrió.",
  ui_story_5061_50610602_27_dialog_content = "Pero independientemente de cuándo ocurrió, no quedan rastros de ello...",
  ui_story_5061_50610602_28_dialog_content = "Tampoco hay rastros de los patrulleros ni de la batalla que libraron en aquel entonces...",
  ui_story_5061_50610602_29_dialog_content = "No puedo creer que mi memoria se haya vuelto tan poco confiable...",
  ui_story_5061_50610602_30_dialog_content = "(¿Eh? Parece que la nieve debajo de nuestros pies está brillando...)",
  ui_story_5061_50610602_31_dialog_content = "¿Hmm? ¿Es ese un conejo junto a ese árbol allá?",
  ui_story_5061_50610602_32_dialog_content = "Los conejos son animales extremadamente cautelosos. Si están afuera, esta área debería estar libre de cualquier peligro oculto...",
  ui_story_5061_50610602_33_dialog_content = "Espera, Zarya! Algo no se siente bien en este lugar. Permíteme intentar usar mis poderes primero.",
  ui_story_5061_50610602_34_dialog_content = "¿Otra vez? Está bien... Si lo peor llega a lo peor, lucharé contra lo que sea que encuentres.",
  ui_story_5061_50610602_35_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50610602_36_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610602_37_dialog_content = "¡Argh!",
  ui_story_5061_50610602_38_dialog_content = "¿Qué fue eso?! Se siente como si algo me hubiera apuñalado la cabeza...",
  ui_story_5061_50610602_39_dialog_content = "¡N-No me asustes así! ¿Estás bien...?",
  ui_story_5061_50610602_40_dialog_content = "Creo... que puede que haya despertado algo...",
  ui_story_5061_50610602_41_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5061_50610602_42_dialog_content = "¿Qué está pasando? ¡¿Qué fue ese ruido?!",
  ui_story_5061_50610602_43_dialog_content = "¡El suelo se está derrumbando!",
  ui_story_5061_50610602_44_dialog_content = "¡Cuidado, Zarya!",
  ui_story_5061_50610602_45_dialog_content = "<color=#e8d9bb>¡Bang—!</color>",
  ui_story_5061_50610602_46_dialog_content = "... ¡Uf!",
  ui_story_5061_50610602_47_dialog_content = "Eso no dolió tanto como pensé que dolería.",
  ui_story_5061_50610602_48_dialog_content = "(No... Sentí como si algo nos atrapara mientras caíamos...)",
  ui_story_5061_50610602_49_dialog_content = "...",
  ui_story_5061_50610602_50_dialog_content = "(De esa manera, parece lo suficientemente seguro, ¿verdad?)",
  ui_story_5061_50610602_51_dialog_content = "Ey, Zarya, deberíamos...",
  ui_story_5061_50610602_52_dialog_content = "¡Oh no, está inconsciente...",
  ui_story_5061_50610701_1_dialog_content = "Zarya, quédate en casa hoy, no vayas a ningún lado, ¿de acuerdo?",
  ui_story_5061_50610701_2_dialog_content = "Pero no he salido de la casa desde hace días...",
  ui_story_5061_50610701_3_dialog_content = "¿Por qué siempre quieres salir? No tienes amigos ni familia que te cuiden. ¿O estás planeando causar problemas con tus Luminatics otra vez?",
  ui_story_5061_50610701_4_dialog_content = "¿Recuerdas cómo congelaste el carruaje la última vez? ¡Cosas así nunca pueden volver a suceder!",
  ui_story_5061_50610701_5_dialog_content = "Yo... entiendo. Lo siento, padre.",
  ui_story_5061_50610701_6_dialog_content = "(Otro día solitario en mi habitación...)",
  ui_story_5061_50610701_7_dialog_content = "Oh, Zarya, mira estas flores, espera, ¿por qué te ves tan decaído?",
  ui_story_5061_50610701_8_dialog_content = "Alina... Papá no me deja salir de la casa otra vez hoy...",
  ui_story_5061_50610701_9_dialog_content = "... Papá está demasiado ocupado con su trabajo como para preocuparse por cualquier otra cosa, Zarya.",
  ui_story_5061_50610701_10_dialog_content = "Tiene miedo de no estar allí para ayudar si algo te sucede. No sabe de qué otra manera protegerte.",
  ui_story_5061_50610701_11_dialog_content = "Lo sé... Todo es porque no puedo controlar mis Luminatics. No soy más que un problema...",
  ui_story_5061_50610701_12_dialog_content = "Eso no es cierto, Zarya. Además, yo solía tener el mismo problema también. ¡Incluso llegué a congelar la puerta principal por accidente!",
  ui_story_5061_50610701_13_dialog_content = "No quería que nadie se enterara, ¡por eso siempre lo abría de una patada primero! ¡Jajaja!",
  ui_story_5061_50610701_14_dialog_content = "Pfft, no puedes engañarme, Alina. ¿Qué clase de capitana de patrulla no puede controlar sus propios poderes?",
  ui_story_5061_50610701_15_dialog_content = "Por supuesto que puedo controlarlos ahora, pero tú eres mucho más poderoso de lo que yo era a tu edad.",
  ui_story_5061_50610701_16_dialog_content = "De hecho, con habilidades como las tuyas, ¡incluso podrías llegar a ser un guardia real en la corte de Queen Bethlehem!",
  ui_story_5061_50610701_17_dialog_content = "¿Una guardia real...? Pero ese siempre ha sido tu sueño, Alina...",
  ui_story_5061_50610701_18_dialog_content = "¡Pero ser patrullero también es genial! Puedo ver todo tipo de lugares lejanos, como montañas nevadas e incluso aguas termales...",
  ui_story_5061_50610701_19_dialog_content = "Y eso no puede ser mucho peor que servir en la Corte, ¿verdad?",
  ui_story_5061_50610701_20_dialog_content = "Eres increíble, Alina... Siempre estás llena de fuerza y motivación, a diferencia de tu hermana inútil y deprimida.",
  ui_story_5061_50610701_21_dialog_content = "¡No te preocupes, Zarya! Pronto serás tan fuerte como yo... No, ¡incluso más fuerte!",
  ui_story_5061_50610701_22_dialog_content = "Además, aún no he renunciado a mi sueño. ¡Estoy seguro de que me convertiré en un guardia real algún día!",
  ui_story_5061_50610701_23_dialog_content = "Y cuando llegue ese día, protegeré a Northland con el Queen!",
  ui_story_5061_50610701_24_dialog_content = "¡Jeje! Sé que puedes hacerlo.",
  ui_story_5061_50610701_25_dialog_content = "¡Uh-oh! Parece que me quedé charlando un poco demasiado tiempo. ¡Ya casi es hora de encontrarme con los otros patrulleros!",
  ui_story_5061_50610701_26_dialog_content = "¡Oh no! Será mejor que te apures, Alina... ¡Buena suerte en tu misión!",
  ui_story_5061_50610701_27_dialog_content = "Gracias. Intenta mantener la cabeza alta, ¿de acuerdo? Recuerda, cuando papá esté enfadado, ¡no tomes demasiado en serio lo que diga!",
  ui_story_5061_50610701_28_dialog_content = "(... Y entonces ella se fue...)",
  ui_story_5061_50610701_29_dialog_content = "(Si supiera lo que pasó después... nunca la habría dejado ir.)",
  ui_story_5061_50610701_30_dialog_content = "(...Pero el pasado nunca se puede cambiar. En mi tristeza y arrepentimiento, lo único que pude hacer fue arriesgar mi vida para enmendar las cosas...)",
  ui_story_5061_50610701_31_dialog_content = "(La última ubicación conocida de su equipo de patrulla... ya estaba llena de Eclipsites...)",
  ui_story_5061_50610701_32_dialog_content = "Alina! ¿Estás ahí afuera?!",
  ui_story_5061_50610701_33_dialog_content = "rugir—",
  ui_story_5061_50610701_34_dialog_content = "¡Mantente fuera de mi camino!",
  ui_story_5061_50610701_35_dialog_content = "¡Alina! ¡Por favor, respóndeme!",
  ui_story_5061_50610701_36_dialog_content = "¡Grrr!",
  ui_story_5061_50610701_37_dialog_content = "¡Muévete!",
  ui_story_5061_50610701_38_dialog_content = "Hermana... ¿Sigues... viva? Estoy tan asustada...",
  ui_story_5061_50610701_39_dialog_content = "... No hay... necesidad de temer.",
  ui_story_5061_50610701_40_dialog_content = "¡...!",
  ui_story_5061_50610701_41_dialog_content = "Esa voz... ¿Eres tú, Alina?",
  ui_story_5061_50610701_42_dialog_content = "... ¿Quieres salvar a alguien?",
  ui_story_5061_50610701_43_dialog_content = "¡Sí! Yo... ¡quiero salvar a mi hermana!",
  ui_story_5061_50610701_44_dialog_content = "... Reconozco tu potencial...",
  ui_story_5061_50610701_45_dialog_content = "... Con contigo, tal vez la misión... podría lograrse...",
  ui_story_5061_50610701_46_dialog_content = "... En ese caso, tomarás... mi soledad...",
  ui_story_5061_50610701_47_dialog_content = "(Y así, seguí esa voz a través de la nieve...)",
  ui_story_5061_50610701_48_dialog_content = "(Pensé que me llevaría a mi hermana, pero en cambio... Me llevó a un infierno que nunca podría haber imaginado.)",
  ui_story_5061_50610701_49_dialog_content = "<color=#e8d9bb>Innumerables patrulleros yacían inmóviles en el suelo.</color>",
  ui_story_5061_50610701_50_dialog_content = "<color=#e8d9bb>Eclipsites con fauces abiertas y una cacofonía de rugidos.</color>",
  ui_story_5061_50610701_51_dialog_content = "<color=#e8d9bb>El hedor nauseabundo, aún penetrante incluso entre la nieve que se arremolina.</color>",
  ui_story_5061_50610701_52_dialog_content = "<color=#e8d9bb>Y el atolladero abisal, viscoso y repugnante en el suelo.</color>",
  ui_story_5061_50610701_53_dialog_content = "Esto no es real... No puede ser real...",
  ui_story_5061_50610701_54_dialog_content = "¡Monstruos sucios! ¡Aléjense de mi hermana!",
  ui_story_5061_50610701_55_dialog_content = "¡Florece, Luz de Hielo!",
  ui_story_5061_50610701_56_dialog_content = "rugir—",
  ui_story_5061_50610701_57_dialog_content = "¡Hay demasiados de ellos! ¡No puedo vencerlos a todos!",
  ui_story_5061_50610701_58_dialog_content = "Rugiiiiiiiido—",
  ui_story_5061_50610701_59_dialog_content = "Lo siento, Alina... ¡No creo que pueda matar a todos estos Eclipsites!",
  ui_story_5061_50610701_60_dialog_content = "Si tan solo fuera más fuerte, quizás podría salvarte ahora...",
  ui_story_5061_50610701_61_dialog_content = "Alina... ¡Alina! ¡Nooooooo!!!",
  ui_story_5061_50610701_62_dialog_content = "<size=45>¡¡¡Alina!!!</size>",
  ui_story_5061_50610701_63_dialog_content = "... Zarya! ¡Despierta!",
  ui_story_5061_50610701_64_dialog_content = "¡Alina!",
  ui_story_5061_50610701_65_dialog_content = "¡Cálmate, Zarya! ¡Fue solo una pesadilla!",
  ui_story_5061_50610701_66_dialog_content = "...",
  ui_story_5061_50610701_67_dialog_content = "¿Recuerdas que el suelo cedió bajo nosotros? Creo que caímos en una cueva o algo así.",
  ui_story_5061_50610701_68_dialog_content = "Parece que hay ruinas atrapadas en el hielo aquí abajo. Voy a echar un vistazo más de cerca...",
  ui_story_5061_50610701_69_dialog_content = "rugir—",
  ui_story_5061_50610701_70_dialog_content = "¡Ah! ¡E-Eclipsites! Oh no, ¿qué debemos hacer? No puedo vencerlos a todos...",
  ui_story_5061_50610701_71_dialog_content = "¿Por qué estás entrando en pánico? ¿Tiene esto algo que ver con tu pesadilla?",
  ui_story_5061_50610701_72_dialog_content = "¡Ponte en marcha, Zarya! ¡No dejes que el pasado interfiera en tu presente!",
  ui_story_5061_50610701_73_dialog_content = "rugir—",
  ui_story_5061_50610701_74_dialog_content = "¿Dónde está la Zarya que conocíamos? ¡La necesitamos ahora más que nunca!",
  ui_story_5061_50610701_75_dialog_content = "Energía—¡Absorción! ¡Rápido, por aquí!",
  ui_story_5061_50610701_76_dialog_content = "¡Esa voz...!",
  ui_story_5061_50610701_77_dialog_content = "Levántate, Zarya! ¡Tenemos que salir de aquí!",
  ui_story_5061_50610702_1_dialog_content = "Deberíamos estar a salvo aquí por ahora.",
  ui_story_5061_50610702_2_dialog_content = "He estado explorando esta área durante un tiempo. Si mi corazonada es correcta, debería haber otra salida cerca, una que conduzca al resto de las ruinas subterráneas de Northland.",
  ui_story_5061_50610702_3_dialog_content = "Esas salidas suelen ser las más peligrosas cuando se trata de estas ruinas.",
  ui_story_5061_50610702_4_dialog_content = "Los Eclipsites a su alrededor están comenzando a descongelarse. Pueden despertar en cualquier momento.",
  ui_story_5061_50610702_5_dialog_content = "Este hielo... Está hecho con la misma Luminatics que la de Zarya, ¿verdad?",
  ui_story_5061_50610702_6_dialog_content = "Así es. De hecho, tengo razones para creer que también fue producido por la misma señorita Zarya.",
  ui_story_5061_50610702_7_dialog_content = "Probablemente fue el resultado explosivo de su poder saliendo de control en el pasado.",
  ui_story_5061_50610702_8_dialog_content = "¿Estás diciendo... que yo hice esto?",
  ui_story_5061_50610702_9_dialog_content = "No se me ocurre una mejor respuesta en este momento, así que sí.",
  ui_story_5061_50610702_10_dialog_content = "Para decir la verdad, señorita Zarya... He querido preguntarte algo desde hace mucho tiempo, pero no he podido encontrar las palabras adecuadas...",
  ui_story_5061_50610702_11_dialog_content = "¿Tiene algo que ver con nuestra situación actual?",
  ui_story_5061_50610702_12_dialog_content = "Por favor, hable con sinceridad, Sr. Antony. Esta es la segunda vez que salva mi vida; responder a sus preguntas es lo menos que puedo hacer.",
  ui_story_5061_50610702_13_dialog_content = "Si tu amabilidad no es suficiente para hacerme aceptar la verdad...",
  ui_story_5061_50610702_14_dialog_content = "Entonces no sé qué lo hará.",
  ui_story_5061_50610702_15_dialog_content = "Muy bien. Comencemos con la fuente de tu poder.",
  ui_story_5061_50610702_16_dialog_content = "Creo que ahora tengo una comprensión básica. La extraña Lumina presente en tu cuerpo se originó en estas ruinas, y parece que te otorgaron este poder por algún propósito desconocido.",
  ui_story_5061_50610702_17_dialog_content = "Para demostrar mi punto... PlayerName, ¿serías tan amable de usar tus propios poderes para escanear el hielo en estas ruinas?",
  ui_story_5061_50610702_18_dialog_content = "Eh... ¡Claro!",
  ui_story_5061_50610702_19_option_content = "Escaneo psíquico",
  ui_story_5061_50610702_20_dialog_content = "Estas formaciones de hielo... Definitivamente fueron influenciadas por Luminatics.",
  ui_story_5061_50610702_21_dialog_content = "¿Mmm? ¡Incluso están emitiendo partículas de Lumina!",
  ui_story_5061_50610702_22_dialog_content = "Esta sensación... No es diferente a cuando sentí el hielo alrededor de Zarya cuando nos conocimos por primera vez.",
  ui_story_5061_50610702_23_dialog_content = "¡Tienes razón! Y cuando me acerco para echar un vistazo...",
  ui_story_5061_50610702_24_dialog_content = "Zarya, ¡tu cabello...!",
  ui_story_5061_50610702_25_dialog_content = "¿Eh? ¿Por qué de repente mi cabello está brillando...?",
  ui_story_5061_50610702_26_dialog_content = "Creo que es un tipo de resonancia. Cuando PlayerName usó sus poderes en el hielo, comenzó a resonar con la Lumina en tu cuerpo.",
  ui_story_5061_50610702_27_dialog_content = "¿Pero no es eso peligroso?",
  ui_story_5061_50610702_28_dialog_content = "No puedo estar seguro... Pero el peligro potencial no es nada comparado con lo que estoy a punto de decir.",
  ui_story_5061_50610702_29_dialog_content = "Qué es...?",
  ui_story_5061_50610702_30_dialog_content = "Cuando aún estábamos en la superficie, basé mi conjetura en el fenómeno reciente conocido como la Aurora tormentosa...",
  ui_story_5061_50610702_31_dialog_content = "Por lo tanto, me fue imposible establecer una cronología para el incidente descrito por la señorita Zarya. De hecho, ni siquiera pude demostrar que haya sucedido alguna vez.",
  ui_story_5061_50610702_32_dialog_content = "Sin embargo, al utilizar el testimonio de la señorita Zarya como base para mi conjetura...",
  ui_story_5061_50610702_33_dialog_content = "Rápidamente me topé con un descubrimiento sorprendente.",
  ui_story_5061_50610702_34_dialog_content = "Es decir, la hermana de la señorita Zarya, una ex capitana de patrulla y miembro honorario de la guardia real de Northland conocida como <color=#FFB400>Alina</color>...",
  ui_story_5061_50610702_35_dialog_content = "Fue una figura prominente que vivió <color=#FFB400>hace muchas décadas</color>!",
  ui_story_5061_50610702_36_dialog_content = "...",
  ui_story_5061_50610702_37_dialog_content = "En otras palabras, la Aurorastorm que experimentaste fue el mismo evento de hace <color=#FFB400>cien años</color>.",
  ui_story_5061_50610702_38_dialog_content = "... ¿Qué?",
  ui_story_5061_50610702_39_dialog_content = "Pero...",
  ui_story_5061_50610702_40_dialog_content = "Pero eso significa... <size=45>Zarya tiene <color=#FFB400>más de cien años</color>???</size>",
  ui_story_5061_50610801_1_dialog_content = "Tiene más libros que una biblioteca... Espera, ¿qué es un \"ready-o\"?",
  ui_story_5061_50610801_2_dialog_content = "PlayerName? También menciona algo llamado \"función de transmisor\". ¿Qué significa eso?",
  ui_story_5061_50610801_3_dialog_content = "Vaya, ¿por qué hablas como mi abuela? ¡Nadie asusta a los niños así en estos días!",
  ui_story_5061_50610801_4_dialog_content = "De hecho, se siente como si estuvieras atrapado en el hielo durante mucho tiempo.",
  ui_story_5061_50610801_5_dialog_content = "(... ¡Por fin entiendo por qué las cosas parecían tan raras ahora!)",
  ui_story_5061_50610801_6_dialog_content = "(Aunque las cosas apenas cambian aquí en Northland, el tiempo sigue siendo igual de implacable que en cualquier otro lugar...",
  ui_story_5061_50610801_7_dialog_content = "(Pasaron cien años mientras Zarya estaba congelado en el hielo...)",
  ui_story_5061_50610801_8_dialog_content = "...",
  ui_story_5061_50610801_9_dialog_content = "No... Esto no puede ser...",
  ui_story_5061_50610801_10_dialog_content = "Debes estar bromeando, ¿verdad, Sr. Antony?",
  ui_story_5061_50610801_11_dialog_content = "Lo siento, pero esta es la verdad.",
  ui_story_5061_50610801_12_dialog_content = "¿La verdad...?",
  ui_story_5061_50610801_13_dialog_content = "Entonces la verdad... ¿es que este mundo está un siglo después de mi propio tiempo?",
  ui_story_5061_50610801_14_dialog_content = "Todos mis seres queridos... mi hermana... ¿Todos se han ido ahora?",
  ui_story_5061_50610801_15_dialog_content = "Y yo... ¿soy el único que queda?",
  ui_story_5061_50610801_16_dialog_content = "Zarya...",
  ui_story_5061_50610801_17_dialog_content = "...",
  ui_story_5061_50610801_18_dialog_content = "... ¡No te creo!",
  ui_story_5061_50610801_19_dialog_content = "Espera, Zarya! ¿A dónde vas?",
  ui_story_5061_50610801_20_dialog_content = "¡No te molestes en seguirme!",
  ui_story_5061_50610801_21_dialog_content = "¿Qué? ¡No puedo dejarte solo aquí adentro!",
  ui_story_5061_50610801_22_dialog_content = "¿Tienes idea de cómo me siento en este momento? Por favor, simplemente no digas ni una palabra más...",
  ui_story_5061_50610801_23_dialog_content = "Lo siento, Zarya, ¡pero tienes que escucharme! ¡Sé exactamente cómo te sientes!",
  ui_story_5061_50610801_24_dialog_content = "¡Sé cómo se siente estar solo en un lugar frío y oscuro!",
  ui_story_5061_50610801_25_dialog_content = "Sé lo difícil que es reaparecer en el mundo, ¡solo para descubrir que todos te han olvidado!",
  ui_story_5061_50610801_26_dialog_content = "Y... sé lo doloroso que es finalmente aprender más sobre tu pasado, solo para encontrarte de nuevo donde comenzaste.",
  ui_story_5061_50610801_27_dialog_content = "...",
  ui_story_5061_50610801_28_dialog_content = "Yo... Yo sabía que algo estaba mal desde el principio...",
  ui_story_5061_50610801_29_dialog_content = "... Pero no quiero aceptar esto. Puede que tengas razón acerca de que mis nuevos poderes no sean míos...",
  ui_story_5061_50610801_30_dialog_content = "Al final, solo soy un cobarde que empeora todo...",
  ui_story_5061_50610801_31_dialog_content = "Ojalá fuera tan valiente como tú...",
  ui_story_5061_50610801_32_dialog_content = "Si tan solo fuera tan fuerte... Como tú o mi hermana... *Sniff*...",
  ui_story_5061_50610801_33_dialog_content = "Waaaaaaah—",
  ui_story_5061_50610801_34_dialog_content = "(Zarya...)",
  ui_story_5061_50610801_35_option_content = "Pon una mano en su hombro",
  ui_story_5061_50610801_36_option_content = "Abrazala suavemente",
  ui_story_5061_50610801_37_dialog_content = "(... No estás solo.)",
  ui_story_5061_50610801_38_dialog_content = "Ahora nos tienes, Zarya... También estamos aquí para ti.",
  ui_story_5061_50610801_39_dialog_content = "Cuando te sientas decaído, solo recuerda... Hay al menos otra persona en el mundo que sabe lo que se siente al ser abandonado por el tiempo.",
  ui_story_5061_50610801_40_dialog_content = "Alguien que todavía se encuentra con todo tipo de problemas para reintegrarse en la sociedad...",
  ui_story_5061_50610801_41_dialog_content = "Yo...",
  ui_story_5061_50610801_42_dialog_content = "Alguien que, a pesar de tener increíbles poderes, aún se le congelan las piernas cuando intenta ayudar a otros necesitados.",
  ui_story_5061_50610801_43_dialog_content = "<color=#e8d9bb>Retumbar-!!!</color>",
  ui_story_5061_50610801_44_dialog_content = "...! ¡¿Qué diablos fue eso?!",
  ui_story_5061_50610801_45_dialog_content = "Un crecimiento anormal en el hielo está causando que esta parte de la cueva se derrumbe.",
  ui_story_5061_50610801_46_dialog_content = "No... Esto es demasiado intenso como para describirlo simplemente como \"anormal\". La resonancia entre Zarya y el hielo podría ser la causa de ello...",
  ui_story_5061_50610801_47_dialog_content = "Aunque también podría ser causado por las ruinas...",
  ui_story_5061_50610801_48_dialog_content = "¡Necesitamos llegar a la salida lo más pronto posible! ¡Podemos encontrarla siguiendo el flujo del aire!",
  ui_story_5061_50610801_49_dialog_content = "¿Puedes pararte, Zarya? ¡Tenemos que irnos!",
  ui_story_5061_50610801_50_dialog_content = "¡Estoy bien!",
  ui_story_5061_50610801_51_dialog_content = "¡Por aquí, PlayerName!",
  ui_story_5061_50610801_52_dialog_content = "Incluso las ruinas están empezando a temblar. ¡Este lugar se va a derrumbar en cualquier momento!",
  ui_story_5061_50610801_53_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5061_50610801_54_dialog_content = "Urg, ¡mi pierna!",
  ui_story_5061_50610801_55_dialog_content = "¡Estás herido!",
  ui_story_5061_50610801_56_dialog_content = "Solo es un rasguño, ¡no te preocupes! ¡Todavía puedo correr!",
  ui_story_5061_50610801_57_dialog_content = "¡Puedo ver la luz a través del techo de la cueva aquí! Ya casi estamos en la salida, ¡apresúrate!",
  ui_story_5061_50610801_58_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5061_50610801_59_dialog_content = "¡Cuida tu cabeza, PlayerName!",
  ui_story_5061_50610801_60_dialog_content = "(Un enorme trozo de hielo está cayendo sobre mí. El dolor en mi pierna me dice que no podré esquivarlo a tiempo...)",
  ui_story_5061_50610801_61_dialog_content = "(Como mínimo... tengo que ayudar a esos dos a escapar...)",
  ui_story_5061_50610801_62_option_content = "Empuja Zarya",
  ui_story_5061_50610801_63_dialog_content = "¡Cuidado, Zarya!",
  ui_story_5061_50610801_64_option_content = "Empujar Antony",
  ui_story_5061_50610801_65_dialog_content = "¡Cuidado, Antony!",
  ui_story_5061_50610801_66_dialog_content = "... ¡Florece, Luz de Hielo!",
  ui_story_5061_50610801_67_dialog_content = "<color=#e8d9bb>Bajo el ataque de Zarya, la enorme roca se hizo añicos en pequeños pedazos y se dispersaron a su alrededor.</color>",
  ui_story_5061_50610801_68_dialog_content = "Zarya... ¡Nos salvaste!",
  ui_story_5061_50610801_69_dialog_content = "Lo sé... Sé que si mi hermana estuviera aquí ahora mismo, no querría que siguiera lamentándome en mi tristeza...",
  ui_story_5061_50610801_70_dialog_content = "Por eso voy a usar mi Luminatics en este hielo y abrir un camino para ti.",
  ui_story_5061_50610801_71_dialog_content = "¡Te dejaré la navegación a ti! Si ves algún Eclipsite, dime dónde están y haré lo que pueda.",
  ui_story_5061_50610801_72_dialog_content = "¡Entendido!",
  ui_story_5061_50610801_73_dialog_content = "Entendido. ¡Nuestro objetivo es la superficie!",
  ui_story_5061_50610802_1_dialog_content = "Ya estamos muy lejos del alcance protector del Faro. Dirigirnos hacia la salida también nos llevará en dirección opuesta al Faro.",
  ui_story_5061_50610802_2_dialog_content = "A partir de ahora, me temo que los Eclipsites solo van a aumentar en fuerza y cantidad.",
  ui_story_5061_50610802_3_dialog_content = "¡...!",
  ui_story_5061_50610802_4_dialog_content = "Yo... siento algo cerca.",
  ui_story_5061_50610802_5_dialog_content = "¿Más Eclipsites?",
  ui_story_5061_50610802_6_dialog_content = "No, eso no es.",
  ui_story_5061_50610802_7_dialog_content = "Sentí una presencia cuando aún estábamos en la superficie. Por lo que puedo decir... Podría ser un Auroriano.",
  ui_story_5061_50610802_8_dialog_content = "¿Un Aurorian? ¿En un lugar como este?",
  ui_story_5061_50610802_9_dialog_content = "Sí, definitivamente es un Aurorian, pero algo se siente diferente.",
  ui_story_5061_50610802_10_dialog_content = "Déjame intentar usar mis poderes de nuevo...",
  ui_story_5061_50610802_11_option_content = "Escaneo psíquico",
  ui_story_5061_50610802_12_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610802_13_dialog_content = "Han pasado tantos años. Me has olvidado durante todos estos años.",
  ui_story_5061_50610802_14_dialog_content = "Ahora, reapareciendo de repente así, ¿para qué? ¿Para el poder de la <color=#FFB400>Chispa</color>?",
  ui_story_5061_50610802_15_dialog_content = "Ha pasado un siglo. ¿Por qué yo, al ser activado de nuevo, tengo tan poca energía mientras que todos ustedes están tan... llenos?",
  ui_story_5061_50610802_16_dialog_content = "Urgh... M-Mi cabeza...",
  ui_story_5061_50610802_17_dialog_content = "¿Qué... estás hablando...?",
  ui_story_5061_50610802_18_dialog_content = "Respóndanme, Aurorianos de la tierra, conductos dispuestos de Lux, receptores de la bendición de la Chispa.",
  ui_story_5061_50610802_19_dialog_content = "Ahh!!!",
  ui_story_5061_50610802_20_dialog_content = "(Mi cabeza se parte en dos... ¡Necesito cortar el enlace!)",
  ui_story_5061_50610802_21_dialog_content = "¡Espera, señorita Zarya!",
  ui_story_5061_50610802_22_dialog_content = "¿Estás bien, PlayerName? ¿Todavía puedes verme? ¿Y esto? ¿Puedes sentir que te pellizco los dedos?",
  ui_story_5061_50610802_23_dialog_content = "Hmm... Sí, puedo sentirte.",
  ui_story_5061_50610802_24_dialog_content = "Bien, tu reacción es normal y tu visión parece estar bien. No parece que te hayas lastimado la cabeza tampoco...",
  ui_story_5061_50610802_25_dialog_content = "Estoy bien, sigamos avanzando. Acabo de sentir a un Aurorian peligroso... Espera, ella...",
  ui_story_5061_50610802_26_dialog_content = "<size=45>... ¡Ella viene!!</size>",
  ui_story_5061_50610802_27_dialog_content = "<color=#e8d9bb>¡Zoom!</color>",
  ui_story_5061_50610802_28_dialog_content = "¡Urgh! M-Mi cuerpo...",
  ui_story_5061_50610802_29_dialog_content = "¿Qué es esto? ¡No puedo controlar el flujo de mi Lumina!",
  ui_story_5061_50610802_30_dialog_content = "Mi cuerpo se siente tan pesado...",
  ui_story_5061_50610802_31_dialog_content = "Me está costando todas mis fuerzas solo ponerme de pie...",
  ui_story_5061_50610802_32_dialog_content = "Espera...",
  ui_story_5061_50610802_33_dialog_content = "Tu Lumina... E incluso la Lumina de las ruinas... ¡Todo está siendo absorbido hacia la misma dirección!",
  ui_story_5061_50610901_1_dialog_content = "<color=#e8d9bb>En el punto final del flujo de Lumina, aparece una figura de blanco inmaculado.</color>",
  ui_story_5061_50610901_2_dialog_content = "<color=#e8d9bb>Su cuerpo flota en el centro del espacio, irradiando una sensación etérea de ingravidez, con la luz celestial en la salida como telón de fondo.</color>",
  ui_story_5061_50610901_3_dialog_content = "<color=#e8d9bb>Mientras se mueve con gracia con esos intrincados miembros mecánicos, toda la ruina parece despertar, emitiendo brillantez y resonando con ella.</color>",
  ui_story_5061_50610901_4_dialog_content = "Aquí estás.",
  ui_story_5061_50610901_5_dialog_content = "¿Eres... un auroriano?",
  ui_story_5061_50610901_6_dialog_content = "Soy... el administrador y guardián de las ruinas, No. 33.",
  ui_story_5061_50610901_7_dialog_content = "Para cumplir la misión, es necesario recuperar energía.",
  ui_story_5061_50610901_8_dialog_content = "Tus acciones... han quebrado los límites de defensa.",
  ui_story_5061_50610901_9_dialog_content = "Tu forma de hablar...",
  ui_story_5061_50610901_10_dialog_content = "¿Qué, Caelestite, piensas emplear tus poderes en mí, lo que desencadenará mi contraataque defensivo?",
  ui_story_5061_50610901_11_dialog_content = "(Esa sensación de que mi mente fue atravesada... ¿Fue eso su \"contraataque defensivo\"?)",
  ui_story_5061_50610901_12_dialog_content = "Ten cuidado, PlayerName. Puedo sentir que algo anda mal con ella.",
  ui_story_5061_50610901_13_dialog_content = "Es como si... algo en ella estuviera roto.",
  ui_story_5061_50610901_14_dialog_content = "Ah, tú, la chica con poderes especiales de Lumina. Me has causado bastantes problemas...",
  ui_story_5061_50610901_15_dialog_content = "¿Yo? ¿Qué hice?",
  ui_story_5061_50610901_16_dialog_content = "Como el bloque de energía de respaldo para la <color=#FFB400>Chispa</color>...",
  ui_story_5061_50610901_17_dialog_content = "Aquí, ¡el orden del flujo de Lumina, suave e ininterrumpido, es crucial!",
  ui_story_5061_50610901_18_dialog_content = "Tu fuerte habilidad de absorción interrumpe todo el sistema, haciendo que mi trabajo de reparación falle una y otra vez.",
  ui_story_5061_50610901_19_dialog_content = "... ¿Habilidad de absorción?",
  ui_story_5061_50610901_20_dialog_content = "Ya veo. Eso podría explicar por qué tu cabello cambió de color, señorita Zarya.",
  ui_story_5061_50610901_21_dialog_content = "Pero si eres el guardián de este lugar, ¿por qué hay Eclipsites deambulando libremente por todas partes?",
  ui_story_5061_50610901_22_dialog_content = "\"¿En todas partes\"? No existe tal concepto. Solo tengo \"aquí.\"",
  ui_story_5061_50610901_23_dialog_content = "Conectado a mí, esta instalación es todo para mí...",
  ui_story_5061_50610901_24_dialog_content = "Mi misión... es <color=#FFB400>mantener el equilibrio de Lumina aquí</color>. Todo lo demás no está relacionado.",
  ui_story_5061_50610901_25_dialog_content = "¿Qué piensas hacer?",
  ui_story_5061_50610901_26_dialog_content = "No es asunto tuyo, forastero. Necesito eliminarla y recuperar la Lumina que robó...",
  ui_story_5061_50610901_27_dialog_content = "La Lumina... ¿que robé? ¿Qué quieres decir con eso?",
  ui_story_5061_50610901_28_dialog_content = "Comando: Destruir.",
  ui_story_5061_50610901_29_dialog_content = "¡Cuidado!",
  ui_story_5061_50610901_30_dialog_content = "¡Alto! ¡Todavía podemos hablar las cosas!",
  ui_story_5061_50610901_31_dialog_content = "Demasiado tarde... Ha pasado mucho tiempo...",
  ui_story_5061_50610901_32_dialog_content = "No voy a perder mi tiempo esperando... y tratando.",
  ui_story_5061_50610901_33_dialog_content = "Ya que no cumplirás con mis instrucciones, solo puedo recurrir al uso de la fuerza...",
  ui_story_5061_50610901_34_dialog_content = "¡Prepárense para la batalla, todos!",
  ui_story_5061_50610902_1_dialog_content = "... ¡Cubierta, Borde de Hielo!",
  ui_story_5061_50610902_2_dialog_content = "¡Ataque al medio ambiente!",
  ui_story_5061_50610902_3_dialog_content = "¡Nuestros ataques no son lo suficientemente fuertes!",
  ui_story_5061_50610902_4_dialog_content = "No podemos lastimarla mientras nuestra Lumina se esté drenando de nuestros cuerpos...",
  ui_story_5061_50610902_5_dialog_content = "¡Cuidado, PlayerName! ¡Ella está atacando!",
  ui_story_5061_50610902_6_dialog_content = "¡Urgh! ... Te tengo.",
  ui_story_5061_50610902_7_dialog_content = "Antony!",
  ui_story_5061_50610902_8_dialog_content = "No te preocupes por mí. Mi Lumina puede que no sea tan poderosa como la de la señorita Zarya, pero mi fuerza física es lo suficientemente confiable.",
  ui_story_5061_50610902_9_dialog_content = "(... ¿Realmente no hay otra manera?)",
  ui_story_5061_50610902_10_dialog_content = "(Ellos me han estado protegiendo todo este tiempo... ¿Realmente no hay nada que pueda hacer para ayudar?)",
  ui_story_5061_50610902_11_dialog_content = "(Tal vez si intento usar mis poderes de nuevo... ¡Podré encontrar su punto débil!)",
  ui_story_5061_50610902_12_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50610902_13_dialog_content = "<color=#e8d9bb>—</color>",
  ui_story_5061_50610902_14_dialog_content = "Urgh—¡Mi cabeza!",
  ui_story_5061_50610902_15_dialog_content = "¡Para, PlayerName!",
  ui_story_5061_50610902_16_dialog_content = "¡Su mente está protegida de tus poderes psíquicos! ¡Solo te lastimarás si los usas!",
  ui_story_5061_50610902_17_dialog_content = "N-no puedo dejar que ustedes hagan toda la pelea... Por eso voy a ayudarles de la única manera que puedo...",
  ui_story_5061_50610902_18_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50610902_19_dialog_content = "Si hay una forma de eludir sus defensas, entonces tal vez pueda—",
  ui_story_5061_50610902_20_dialog_content = "¡Argh...! ¡Mi cabeza está a punto de estallar!",
  ui_story_5061_50610902_21_dialog_content = "Rayos... Incluso si lo sostengo, no puedo evitar que PlayerName use sus poderes.",
  ui_story_5061_50610902_22_dialog_content = "¡Eso es suficiente! ¡Solo para!",
  ui_story_5061_50610902_23_dialog_content = "No puedes seguir lastimándote así, PlayerName!",
  ui_story_5061_50610902_24_dialog_content = "Eso también va para ti, Sr. Antony!",
  ui_story_5061_50610902_25_dialog_content = "Les debo la vida a los dos. No puedo soportar verlos lastimarse más.",
  ui_story_5061_50610902_26_dialog_content = "Sois buenas personas y todavía tenéis metas que perseguir en la vida.",
  ui_story_5061_50610902_27_dialog_content = "Espera, Zarya, ¿qué quieres decir con eso...?",
  ui_story_5061_50610902_28_dialog_content = "He perdido a mi hermana, mi familia y la vida que solía tener...",
  ui_story_5061_50610902_29_dialog_content = "Ya no tengo adónde ir, ningún lugar al que llamar \"hogar\"... Solo soy una cáscara vacía de la persona que solía ser.",
  ui_story_5061_50610902_30_dialog_content = "Por eso no me importa lo que me pase ahora.",
  ui_story_5061_50610902_31_dialog_content = "Pero al menos ustedes dos—",
  ui_story_5061_50610902_32_dialog_content = "¿¡Qué demonios crees que estás haciendo, Zarya?!",
  ui_story_5061_50610902_33_dialog_content = "<color=#e8d9bb>Crujido-</color>",
  ui_story_5061_50610902_34_dialog_content = "¡Espera, Zarya—!",
  ui_story_5061_50610902_35_dialog_content = "Tu debes vivir.",
  ui_story_5061_50610902_36_dialog_content = "Zarya!!!",
  ui_story_5061_50610902_37_dialog_content = "<size=45>¡¡¡Zaryaaaaaaaa!!!</size>",
  ui_story_5061_50611001_1_dialog_content = "(Zarya utilizó una columna de hielo para llevarnos a salvo al exterior...)",
  ui_story_5061_50611001_2_dialog_content = "(Poco después, la salida de la cueva se derrumbó por completo.)",
  ui_story_5061_50611001_3_dialog_content = "¿Por qué... Por qué no me di cuenta antes?!",
  ui_story_5061_50611001_4_dialog_content = "No... Esto no puede ser...",
  ui_story_5061_50611001_5_dialog_content = "Si tan solo fuera tan fuerte... Como tú o mi hermana... *Sniff*...",
  ui_story_5061_50611001_6_dialog_content = "Waaaaaaaaaaah—",
  ui_story_5061_50611001_7_dialog_content = "Tu debes vivir.",
  ui_story_5061_50611001_8_dialog_content = "Ojalá fuera tan fuerte como tú...",
  ui_story_5061_50611001_9_dialog_content = "En el momento en que Zarya supo la verdad, perdió toda esperanza en su corazón.",
  ui_story_5061_50611001_10_dialog_content = "Apenas dijo una palabra después de eso. Simplemente nos siguió mientras corríamos y luchábamos para salir...",
  ui_story_5061_50611001_11_dialog_content = "Lo siento. También debería haberme dado cuenta de que algo estaba mal.",
  ui_story_5061_50611001_12_dialog_content = "Está allí sola, atrapada en las ruinas sin salida... Y eso es exactamente lo que quiere.",
  ui_story_5061_50611001_13_dialog_content = "... Necesitamos regresar y salvarla, pero ¿cómo? No puedo luchar como ustedes, y mis poderes psíquicos solo me perjudican.",
  ui_story_5061_50611001_14_dialog_content = "No solo eso... ¡No. 33 simplemente drenará tu Lumina si volvemos a enfrentarnos a ella! ¿Qué debemos hacer?!",
  ui_story_5061_50611001_15_dialog_content = "Al menos por ahora, podemos confiar en que la fuerza de la señorita Zarya no le fallará pronto. No caerá sin dar pelea.",
  ui_story_5061_50611001_16_dialog_content = "Incluso mientras su Lumina se agotaba en la batalla, aún tenía suficiente para generar una columna de hielo que nos llevó a un lugar seguro.",
  ui_story_5061_50611001_17_dialog_content = "Además... Alguien dispuesto a aventurarse en un lugar peligroso por su cuenta no renunciará a su vida tan fácilmente.",
  ui_story_5061_50611001_18_dialog_content = "Entonces, ¿hay algo que podamos hacer para ayudar a Zarya ahora mismo?",
  ui_story_5061_50611001_19_dialog_content = "...Hay.",
  ui_story_5061_50611001_20_dialog_content = "Este lugar está mucho más allá de la frontera noroeste de Northland, pero con tu ayuda, deberíamos estar bien.",
  ui_story_5061_50611001_21_dialog_content = "Que necesitas que haga?",
  ui_story_5061_50611001_22_dialog_content = "Necesito que encuentres el conejo más cercano a nosotros.",
  ui_story_5061_50611001_23_dialog_content = "¿Un conejo?",
  ui_story_5061_50611001_24_dialog_content = "Correcto. Es un animal blanco y esponjoso de este tamaño, con orejas largas y—",
  ui_story_5061_50611001_25_dialog_content = "Sé lo que es un conejo, Antony. Simplemente no sé por qué necesitas uno ahora mismo.",
  ui_story_5061_50611001_26_dialog_content = "Oh, ¿de verdad? Entonces no deberías tener problemas para encontrar uno.",
  ui_story_5061_50611001_27_dialog_content = "Debería haber uno al sureste... Pero no puedo decir qué tan lejos está. ¿Crees que podrías echarme una mano?",
  ui_story_5061_50611001_28_dialog_content = "(... Supongo que tendré que hacer lo que dice por ahora.)",
  ui_story_5061_50611001_29_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50611001_30_dialog_content = "(¿Al sureste, eh? Espera... ¿No vimos un conejo Zarya y yo en el camino aquí?)",
  ui_story_5061_50611001_31_dialog_content = "(... ¡Lo hicimos! ¡Y está justo allí!)",
  ui_story_5061_50611001_32_dialog_content = "(El conejo parece haber notado algo también. Está mirando en nuestra dirección.)",
  ui_story_5061_50611001_33_dialog_content = "Encontré uno, Antony.",
  ui_story_5061_50611001_34_dialog_content = "R-¿En serio? ¡Eso fue rápido! ¡Tus habilidades psíquicas son realmente impresionantes!",
  ui_story_5061_50611001_35_dialog_content = "Je... Están bien, supongo...",
  ui_story_5061_50611001_36_dialog_content = "De todos modos, deberíamos ponernos en marcha.",
  ui_story_5061_50611001_37_dialog_content = "¡Aquí!",
  ui_story_5061_50611001_38_dialog_content = "¡Excelente! Si no me equivoco, este conejo es uno de los compañeros de <color=#FFB400>él</color>.",
  ui_story_5061_50611001_39_dialog_content = "Hola, mi pequeño amigo! ¿Podrías ayudarnos a enviar un mensaje a tu maestro, el <color=#FFB400>espíritu de la montaña</color>? Por favor, dile que encontramos un conjunto olvidado de ruinas aquí, así como un ciudadano perdido hace mucho tiempo de Northland.",
  ui_story_5061_50611001_40_dialog_content = "<color=#e8d9bb>El conejo salta lejos, muy lejos en dirección a Northland.</color>",
  ui_story_5061_50611001_41_dialog_content = "Un \"conjunto olvidado de ruinas\"... ¿Crees que tiene algo que ver con la \"<color=#FFB400>Chispa</color>\" que mencionó el Aurorian anteriormente?",
  ui_story_5061_50611001_42_dialog_content = "Creo que sí. Si lo que ella dice es cierto, estas ruinas sirven como fuente de energía para la Chispa.",
  ui_story_5061_50611001_43_dialog_content = "La Chispa, a su vez, alimenta las defensas de nuestro reino. Por lo tanto, estas ruinas son las más importantes de toda Northland.",
  ui_story_5061_50611001_44_dialog_content = "El <color=#FFB400>Faro</color>, que proyecta la barrera que protege a nuestro reino entero de los Eclipsites, también es parte de la Chispa.",
  ui_story_5061_50611001_45_dialog_content = "¿Eso significa que el guardián loco con el que nos encontramos también es parte de las defensas de Northland?",
  ui_story_5061_50611001_46_dialog_content = "Creo que solo el Queen y el espíritu de la montaña tienen acceso a ese conocimiento.",
  ui_story_5061_50611002_1_dialog_content = "¡Nunca me rendiré!",
  ui_story_5061_50611002_2_dialog_content = "(No tengo suficiente Lumina para lastimarla...)",
  ui_story_5061_50611002_3_dialog_content = "(También... No solo se ve diferente a otros aurorianos, sino que sus acciones y patrones de habla también son realmente extraños...)",
  ui_story_5061_50611002_4_dialog_content = "He querido preguntarte algo...",
  ui_story_5061_50611002_5_dialog_content = "¿Por qué... Por qué tu voz suena igual que la de mi hermana?!",
  ui_story_5061_50611002_6_dialog_content = "Mi voz...",
  ui_story_5061_50611002_7_dialog_content = "La voz de la señorita Alina...",
  ui_story_5061_50611002_8_dialog_content = "¿Sabes quién es ella? ¡Dime, qué le has hecho a mi hermana?!",
  ui_story_5061_50611002_9_dialog_content = "La conocí en persona... Hicimos un pacto temporal...",
  ui_story_5061_50611002_10_dialog_content = "Me convertí en un recipiente de energía para ejecutar el protocolo de limpieza máxima y dispersar a los Eclipsites...",
  ui_story_5061_50611002_11_dialog_content = "...¿Qué quieres decir?",
  ui_story_5061_50611002_12_dialog_content = "Alina estuvo aquí una vez... y me encontró.",
  ui_story_5061_50611002_13_dialog_content = "El exterior estaba lleno de Eclipsites y su energía estaba agotada... No puedo irme...",
  ui_story_5061_50611002_14_dialog_content = "Una situación desesperada. Alina, ella absorbió toda la energía aquí y se convirtió en el recipiente. La única solución...",
  ui_story_5061_50611002_15_dialog_content = "Entonces, para derrotar a los Eclipsites... ¿Convertiste a mi hermana en un recipiente para el Lumina de estas ruinas?",
  ui_story_5061_50611002_16_dialog_content = "Pero el cuerpo de un auroriano no puede contener tanta Lumina... ¿O sí?",
  ui_story_5061_50611002_17_dialog_content = "No puede ser... Ella sabía que sacrificaría su vida. No había otra salida.",
  ui_story_5061_50611002_18_dialog_content = "... Está bien. No nos quedan más opciones.",
  ui_story_5061_50611002_19_dialog_content = "¿Realmente lo has pensado bien?",
  ui_story_5061_50611002_20_dialog_content = "Has protegido este lugar durante tanto tiempo... Pero ahora es el momento de que uno de nosotros te proteja.",
  ui_story_5061_50611002_21_dialog_content = "No solo eso... Pero también quiero proteger nuestro mundo por el bien de mi hermana.",
  ui_story_5061_50611002_22_dialog_content = "Admiro tu coraje. Comencemos...",
  ui_story_5061_50611002_23_dialog_content = "Gracias... Espíritu de la Aurora. Dejo el resto en tus manos ahora.",
  ui_story_5061_50611002_24_dialog_content = "Pero yo...",
  ui_story_5061_50611002_25_dialog_content = "Pero espero que puedas sobrevivir.",
  ui_story_5061_50611002_26_dialog_content = "Mi primer amigo auroriano que vive en la superficie.",
  ui_story_5061_50611002_27_dialog_content = "Cálculo... comenzando el cálculo...",
  ui_story_5061_50611002_28_dialog_content = "El método para asegurar tu supervivencia...",
  ui_story_5061_50611002_29_dialog_content = "¿Es realmente así... cómo mi hermana se sacrificó?",
  ui_story_5061_50611002_30_dialog_content = "... Urgh... Alina... Alina...",
  ui_story_5061_50611002_31_dialog_content = "¡Error en la Plantilla de Eco!",
  ui_story_5061_50611002_32_dialog_content = "Intentando reiniciar.",
  ui_story_5061_50611002_33_dialog_content = "Para proteger a todos de la Tormenta Auroriana... para protegerme a mí...",
  ui_story_5061_50611101_1_dialog_content = "¡Error en la Plantilla de Eco!",
  ui_story_5061_50611101_2_dialog_content = "Reinicio, error; reinicio, error; reinicio—",
  ui_story_5061_50611101_3_dialog_content = "Advertencia: Intrusos detectados dentro de la instalación;",
  ui_story_5061_50611101_4_dialog_content = "Eliminar, eliminar;",
  ui_story_5061_50611101_5_dialog_content = "¿Qué está pasando? ¡Oye! ¡Aún no hemos terminado de hablar!",
  ui_story_5061_50611101_6_dialog_content = "¿Por qué te está pasando esto de repente otra vez? ¿Necesitas que te refresque de nuevo?!",
  ui_story_5061_50611101_7_dialog_content = "Custodiar este lugar, mi única misión;",
  ui_story_5061_50611101_8_dialog_content = "Todo lo demás, irrelevante, eliminar;",
  ui_story_5061_50611101_9_dialog_content = "¡¿De qué estás hablando?!",
  ui_story_5061_50611101_10_dialog_content = "¿No dijiste que protegiste a todos con la ayuda de mi hermana?",
  ui_story_5061_50611101_11_dialog_content = "¡¿No me digas que lo has olvidado?!",
  ui_story_5061_50611101_12_dialog_content = "Plantilla reiniciada... Se encontró un error desconocido;",
  ui_story_5061_50611101_13_dialog_content = "Vengan, todos.",
  ui_story_5061_50611101_14_dialog_content = "Debemos descender lo más suavemente posible...",
  ui_story_5061_50611101_15_dialog_content = "¡Puedo ver el fondo!",
  ui_story_5061_50611101_16_dialog_content = "¡Mira! ¡Es la señorita Zarya!",
  ui_story_5061_50611101_17_dialog_content = "Zarya! ¡Hemos vuelto para salvarte!",
  ui_story_5061_50611101_18_dialog_content = "¿Qué...? ¿Por qué? ¿Tienes idea de lo difícil que fue sacarte de aquí?!",
  ui_story_5061_50611101_19_dialog_content = "¡Te lo dije antes! ¡Ya no estás solo!",
  ui_story_5061_50611101_20_dialog_content = "Tú... No puedo... ¡Ugh, qué se supone que debo hacer contigo?!",
  ui_story_5061_50611101_21_dialog_content = "¡Estaremos bien! Además, ¡hemos ideado un plan!",
  ui_story_5061_50611101_22_dialog_content = "... ¿Un plan?",
  ui_story_5061_50611101_23_dialog_content = "¿No has notado que tu Lumina ya no se está agotando?",
  ui_story_5061_50611101_24_dialog_content = "...¡Tienes razón!",
  ui_story_5061_50611101_25_dialog_content = "Ahora, todo lo que necesitamos hacer es limitar los movimientos de No. 33.",
  ui_story_5061_50611101_26_dialog_content = "¡Una vez que lo hagamos, esperaré el momento adecuado para usar mis poderes en ella!",
  ui_story_5061_50611101_27_dialog_content = "¿Te has vuelto loco, PlayerName?! ¿Ya has olvidado lo que eso te hace?!",
  ui_story_5061_50611101_28_dialog_content = "La <color=#FFB400>Plantilla de Eco</color> de No. 33 sigue produciendo errores debido al daño que ha sufrido, así como a su activación poco ortodoxa.",
  ui_story_5061_50611101_29_dialog_content = "El único que puede reparar su plantilla de eco es PlayerName, y solo utilizando sus poderes.",
  ui_story_5061_50611101_30_dialog_content = "También contamos con la protección de <color=#FFB400>él</color>, así que no deberíamos encontrar más resistencia.",
  ui_story_5061_50611101_31_dialog_content = "¿Estás listo, Zarya?",
  ui_story_5061_50611101_32_dialog_content = "... Sí. ¡Creo en ti!",
  ui_story_5061_50611101_33_dialog_content = "¡Hagámoslo!",
  ui_story_5061_50611102_1_dialog_content = "¡Ella está reduciendo la velocidad!",
  ui_story_5061_50611102_2_dialog_content = "Estoy listo.",
  ui_story_5061_50611102_3_dialog_content = "Ya no hay nada que temer.",
  ui_story_5061_50611102_4_dialog_content = "—!",
  ui_story_5061_50611102_5_dialog_content = "¡Hazlo, PlayerName!",
  ui_story_5061_50611102_6_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50611102_7_dialog_content = "(¡...!)",
  ui_story_5061_50611102_8_dialog_content = "(Nunca antes había sentido algo así...)",
  ui_story_5061_50611102_9_dialog_content = "(Mi conciencia... sigue avanzando hacia adelante...)",
  ui_story_5061_50611102_10_dialog_content = "(En el mundo real, todo esto sucede en un solo instante, pero siento como si mi mente hubiera estado flotando eternamente en un mar de tiempo—)",
  ui_story_5061_50611201_1_dialog_content = "<color=#e8d9bb>Hace █████ años, la Instalación de Suministro de Energía Chispa N.º ███.</color>",
  ui_story_5061_50611201_2_dialog_content = "La lente auxiliar se desvió por 4682ª vez; la distancia focal necesita recalibración.",
  ui_story_5061_50611201_3_dialog_content = "...",
  ui_story_5061_50611201_4_dialog_content = "La calibración falló. Motivo: Daño irreparable al soporte auxiliar de lente Nº 44.",
  ui_story_5061_50611201_5_dialog_content = "Solución: Reemplázalo con el soporte de respaldo No. 863.",
  ui_story_5061_50611201_6_dialog_content = "... Componentes dañados reemplazados. Inventario restante: 3264 unidades.",
  ui_story_5061_50611201_7_dialog_content = "Inspección completada; no se encontraron anomalías. El mantenimiento de rutina de hoy también está terminado.",
  ui_story_5061_50611201_8_dialog_content = "<color=#e8d9bb>No. 33 está asignado para mantener varios dispositivos dentro de la pequeña instalación en la que se encuentra, especialmente el Concentrador de Lumina.</color>",
  ui_story_5061_50611201_9_dialog_content = "<color=#e8d9bb>Desde su despertar en la instalación, ha estado trabajando diligentemente en el mantenimiento, cumpliendo fielmente con la misión que se le ha encomendado.</color>",
  ui_story_5061_50611201_10_dialog_content = "El conducto de Lumina ha encontrado un bloqueo por 78,643ª vez y requiere ser despejado.",
  ui_story_5061_50611201_11_dialog_content = "... Intento de despeje fallido. Motivo: Daño irreparable en la interfaz del conducto 65 del oleoducto.",
  ui_story_5061_50611201_12_dialog_content = "Solución: Reemplazarlo con el tubo de repuesto 264; Stock restante: 0 unidades.",
  ui_story_5061_50611201_13_dialog_content = "Busca oleoductos alternativos para usar. Oleoducto 195, inventario: 0 unidades; Oleoducto 236, inventario: 0 unidades.",
  ui_story_5061_50611201_14_dialog_content = "No hay tuberías de reemplazo disponibles; Buscando tuberías en uso adecuadas para sustitución...",
  ui_story_5061_50611201_15_dialog_content = "Encontré una tubería adecuada en la interfaz de la rama 80, con una tasa de degradación del 39%. Preparándose para la eliminación y reemplazo en la interfaz 65.",
  ui_story_5061_50611201_16_dialog_content = "... Componente dañado reemplazado.",
  ui_story_5061_50611201_17_dialog_content = "El sistema funciona normalmente, salida de energía: 60%.",
  ui_story_5061_50611201_18_dialog_content = "...",
  ui_story_5061_50611201_19_dialog_content = "(... Para reemplazar los componentes del Concentrador de Lumina, todos los dispositivos circundantes fueron desmantelados ...)",
  ui_story_5061_50611201_20_dialog_content = "<color=#e8d9bb>Pero No. 33 no es solo una máquina; es una Auroriana con su cuerpo y órganos significativamente modificados.</color>",
  ui_story_5061_50611201_21_dialog_content = "<color=#e8d9bb>Con el tiempo, ella también experimentaría soledad, cansándose de la vida inmutable dentro de la instalación subterránea.</color>",
  ui_story_5061_50611201_22_dialog_content = "<color=#e8d9bb>Y entonces, comenzó a cuestionar el propósito de su propia misión.</color>",
  ui_story_5061_50611201_23_dialog_content = "... Debido a la eliminación de las fuentes de energía de respaldo, el sistema de calefacción ha estado inactivo durante 436 días.",
  ui_story_5061_50611201_24_dialog_content = "(Debe estar bastante frío ahora... pero ya no puedo sentirlo...)",
  ui_story_5061_50611201_25_dialog_content = "(... ¿Es realmente significativo todo lo que he hecho?)",
  ui_story_5061_50611201_26_dialog_content = "(Han pasado tantos años y nadie ha venido aquí ni sabe lo que he estado haciendo.)",
  ui_story_5061_50611201_27_dialog_content = "(¿Todavía es necesario que continúe mi misión?)",
  ui_story_5061_50611201_28_dialog_content = "Busca módulos de almacenamiento de datos alternativos que puedan reemplazar el actual en uso.",
  ui_story_5061_50611201_29_dialog_content = "No hay módulos de almacenamiento sin usar. Busca módulos reemplazables en uso activo...",
  ui_story_5061_50611201_30_dialog_content = "No. 33Dispositivo de mantenimiento biológico, cabeza, Módulo de almacenamiento 2, con una tasa de degradación del 32%.",
  ui_story_5061_50611201_31_dialog_content = "(No. 33... ¿Eh?)",
  ui_story_5061_50611201_32_dialog_content = "(¿Mi... cabeza? ¿Mi... módulo de almacenamiento?)",
  ui_story_5061_50611201_33_dialog_content = "...",
  ui_story_5061_50611201_34_dialog_content = "(Bueno, a estas alturas, ¿qué hay para arrepentirse?)",
  ui_story_5061_50611201_35_dialog_content = "(... Ya he eliminado muchas partes antes de todos modos. Mis sentidos ya no son como los de un Aurorian vivo...)",
  ui_story_5061_50611201_36_dialog_content = "... Componentes dañados reemplazados. El sistema funciona normalmente, salida de energía: 19%.",
  ui_story_5061_50611201_37_dialog_content = "(A pesar del bajo rendimiento energético, no ha habido desastres ni accidentes.)",
  ui_story_5061_50611201_38_dialog_content = "(Aparte de aquí, hay numerosas otras instalaciones en funcionamiento.)",
  ui_story_5061_50611201_39_dialog_content = "(Conmigo o sin mí, no hay mucha diferencia.)",
  ui_story_5061_50611201_40_dialog_content = "(...¿Este lugar... todavía tiene un propósito?)",
  ui_story_5061_50611201_41_dialog_content = "<color=#e8d9bb>A medida que sus componentes vitales se desmantelan gradualmente, No. 33 debe entrar en períodos prolongados de hibernación para preservar sus funciones de supervivencia.</color>",
  ui_story_5061_50611201_42_dialog_content = "<color=#e8d9bb>Ella despertaría de nuevo en varios años; luego la próxima vez sería más de una década después, y luego varias décadas después...</color>",
  ui_story_5061_50611201_43_dialog_content = "<color=#e8d9bb>Hace 100 años, la Instalación de Suministro de Energía Chispa N.º ███.</color>",
  ui_story_5061_50611201_44_dialog_content = "<color=#e8d9bb><size=45>Retumbar—</size></color>",
  ui_story_5061_50611201_45_dialog_content = "(¿Qué... Qué está pasando!)",
  ui_story_5061_50611201_46_dialog_content = "(Ugh... Despertar de la hibernación, me duele la cabeza... ¡Diagnóstico de emergencia!)",
  ui_story_5061_50611201_47_dialog_content = "(El depósito de energía sufrió daños irreparables; la Lumina de alta pureza se está dispersando, causando una <color=#FFB400>explosión de energía</color> en la superficie;)",
  ui_story_5061_50611201_48_dialog_content = "(¿Por qué, de todos los componentes, es el depósito de energía? Es la parte más robusta del concentrador... ¿cómo podría estar dañado...)",
  ui_story_5061_50611201_49_dialog_content = "(... Oh, cierto... porque ha pasado tanto tiempo... suficiente para que todo se deteriore...)",
  ui_story_5061_50611201_50_dialog_content = "(... ¿Cuántos años han pasado? No puedo recordarlo con algunos de los módulos de almacenamiento perdidos...)",
  ui_story_5061_50611201_51_dialog_content = "rugir—",
  ui_story_5061_50611201_52_dialog_content = "(¿Eclipsites están aquí?... Es cierto, los sistemas de defensa fallaron hace mucho tiempo...)",
  ui_story_5061_50611201_53_dialog_content = "(... Todo aquí... está dañado...)",
  ui_story_5061_50611201_54_dialog_content = "(Ahhh... al fin... ¿todo está finalmente llegando a su fin...)",
  ui_story_5061_50611201_55_dialog_content = "(En los últimos momentos, nadie sigue siendo consciente de todo lo que he hecho a lo largo de los años...)",
  ui_story_5061_50611201_56_dialog_content = "(Ya hace tiempo acepté mi destino de colapsar junto con este lugar...)",
  ui_story_5061_50611201_57_dialog_content = "(Aun así, nadie sabe de mi existencia, nadie está consciente de las contribuciones que he hecho...)",
  ui_story_5061_50611201_58_dialog_content = "(Cualquiera servirá... al menos, ven... y échame un vistazo...)",
  ui_story_5061_50611201_59_dialog_content = "(Alguien...)",
  ui_story_5061_50611201_60_dialog_content = "Dónde estoy...?",
  ui_story_5061_50611201_61_dialog_content = "!",
  ui_story_5061_50611201_62_dialog_content = "¿Mmm? ¿Eres... un auroriano?",
  ui_story_5061_50611201_63_dialog_content = "—",
  ui_story_5061_50611201_64_dialog_content = "(Mi plantilla de eco ya no puede ayudarme a hacer sonidos. Así que solo puedo extender mi mano instintivamente...)",
  ui_story_5061_50611201_65_dialog_content = "(Extiendo mi mano hacia la que me salvó de la soledad interminable: la señorita Alina.)",
  ui_story_5061_50611201_66_dialog_content = "(Usé una \"parte\" de la señorita Alina para reparar mi plantilla de eco, lo que me permite hacer sonidos...)",
  ui_story_5061_50611201_67_dialog_content = "(Le relato mi misión y ella me cuenta lo que ha sucedido en la superficie.)",
  ui_story_5061_50611201_68_dialog_content = "(La explosión de energía provocada por el mal funcionamiento del Concentrador de Lumina es llamada <color=#FFB400>Aurorastorm</color> por aquellos en el exterior.)",
  ui_story_5061_50611201_69_dialog_content = "La Lumina anormal producida por la Aurorastorm atrajo a un gran número de Eclipsites.",
  ui_story_5061_50611201_70_dialog_content = "(La deterioración de la instalación... provoca anomalías en la Lumina externa, Eclipsites descontrolados y pone en peligro la supervivencia de los Aurorians en la superficie.)",
  ui_story_5061_50611201_71_dialog_content = "(Siempre pensé que mi misión era mantener los dispositivos en funcionamiento.)",
  ui_story_5061_50611201_72_dialog_content = "(Entonces, en realidad, ¿mi verdadero propósito es mantener el ambiente para la supervivencia de los aurorianos?)",
  ui_story_5061_50611201_73_dialog_content = "Lo siento, pero no puedo salir de este lugar. Desconectar podría resultar en una inestabilidad aún más grave en las instalaciones.",
  ui_story_5061_50611201_74_dialog_content = "Aunque la condición de las instalaciones ya no me preocupa, no quiero que el mundo exterior sufra desastres aún más terribles de los que ya enfrenta.",
  ui_story_5061_50611201_75_dialog_content = "¿Realmente no hay otra manera?",
  ui_story_5061_50611201_76_dialog_content = "... Con el equipo aquí, puedo concentrar el Lumina que estalla aquí en ti, permitiéndote liberar esta energía en los Eclipsites afuera...",
  ui_story_5061_50611201_77_dialog_content = "De esta manera, puedes repeler la oleada de Eclipsites y detener la expansión de la Auroratormenta.",
  ui_story_5061_50611201_78_dialog_content = "Pero el cuerpo de un auroriano no puede soportar tal cantidad de energía, lo que significa que probablemente te desintegrarías en unos pocos minutos.",
  ui_story_5061_50611201_79_dialog_content = "(¿La única luz que he anhelado durante este largo período, realmente la voy a alejar con mis propias manos...)",
  ui_story_5061_50611201_80_dialog_content = "... Está bien. No nos quedan más opciones.",
  ui_story_5061_50611201_81_dialog_content = "(Por favor, te lo suplico, no te sacrifiques. Eres la luz que he estado esperando con tanto esfuerzo ver.)",
  ui_story_5061_50611201_82_dialog_content = "¿Realmente lo has pensado bien?",
  ui_story_5061_50611201_83_dialog_content = "Has protegido este lugar durante tanto tiempo... Pero ahora es el momento de que uno de nosotros te proteja.",
  ui_story_5061_50611201_84_dialog_content = "No solo eso... Pero también quiero proteger nuestro mundo por el bien de mi hermana.",
  ui_story_5061_50611201_85_dialog_content = "(¡No... No quiero perderte!)",
  ui_story_5061_50611201_86_dialog_content = "Admiro tu coraje. Comencemos...",
  ui_story_5061_50611201_87_dialog_content = "Estos deben ser... ¡los recuerdos de No. 33!",
  ui_story_5061_50611201_88_dialog_content = "¿Está funcionando, PlayerName?",
  ui_story_5061_50611201_89_dialog_content = "¡Es cierto! ¡Sus recuerdos están en proceso de recuperación!",
  ui_story_5061_50611201_90_dialog_content = "Sí, ahora lo recuerdo. Mi misión no es solo proteger este lugar...",
  ui_story_5061_50611201_91_dialog_content = "Y además, ¿para proteger el mundo exterior? Alina—",
  ui_story_5061_50611201_92_dialog_content = "¡Error en la Plantilla de Eco!",
  ui_story_5061_50611201_93_dialog_content = "Entonces, ¿por qué no mejora?",
  ui_story_5061_50611201_94_dialog_content = "¡Necesito usar mis poderes una vez más! Esta vez, estoy seguro de que puedo llegar al núcleo de su conciencia.",
  ui_story_5061_50611201_95_dialog_content = "Forzando el apagado del módulo de memoria...",
  ui_story_5061_50611201_96_dialog_content = "¡No! ¡No! ¡No quiero olvidarla!",
  ui_story_5061_50611201_97_dialog_content = "<size=45>¡Sálvame! ¡SÁLVAME! ¡AHHHHH!</size>",
  ui_story_5061_50611202_1_dialog_content = "Ughhhhh...",
  ui_story_5061_50611202_2_dialog_content = "¡Se detuvo!",
  ui_story_5061_50611202_3_dialog_content = "Tienes que ayudarla, PlayerName!",
  ui_story_5061_50611202_4_option_content = "¡Potencia de fuerza!",
  ui_story_5061_50611202_5_dialog_content = "<color=#e8d9bb>En el insondable mar de la conciencia, una figura frágil se acurruca.</color>",
  ui_story_5061_50611202_6_dialog_content = "Mi... mi misión, mi misión es...",
  ui_story_5061_50611202_7_dialog_content = "¡El concentrador de Lumina ha sido desechado! Ahora solo necesito apagarlo y cerrar este lugar.",
  ui_story_5061_50611202_8_dialog_content = "Sé que ha sido difícil para ti todos estos años, pero tu misión finalmente está completa.",
  ui_story_5061_50611202_9_dialog_content = "¡...!",
  ui_story_5061_50611202_10_dialog_content = "Lamento que nos haya llevado tanto tiempo encontrarte. Debes haber estado muy solo todo este tiempo.",
  ui_story_5061_50611202_11_dialog_content = "¡¿Por qué?! ¿Por qué solo vienes a mí ahora?",
  ui_story_5061_50611202_12_dialog_content = "La Lumina ha estado obstruida durante tanto tiempo, las reliquias han estado dañadas durante tanto tiempo y yo he estado equivocada durante tanto tiempo...",
  ui_story_5061_50611202_13_dialog_content = "Ya he decidido rendirme...",
  ui_story_5061_50611202_14_dialog_content = "Pero nunca te rendiste, ¿verdad? Y por eso, siempre estaremos agradecidos.",
  ui_story_5061_50611202_15_dialog_content = "...",
  ui_story_5061_50611202_16_dialog_content = "Northland ha estado en paz durante tantos años, todo gracias a que nunca te rendiste.",
  ui_story_5061_50611202_17_dialog_content = "Los lugares que no estaban bajo la protección de estas ruinas fueron invadidos por los Eclipsites en muy poco tiempo.",
  ui_story_5061_50611202_18_dialog_content = "Pero la gente de Northland ha vivido vidas felices y pacíficas durante mucho tiempo... Y todo es gracias a ti.",
  ui_story_5061_50611202_19_dialog_content = "... ¿En serio, por mi culpa?",
  ui_story_5061_50611202_20_dialog_content = "Mi misión... ¿tiene significado?",
  ui_story_5061_50611202_21_dialog_content = "¡Por supuesto que sí! Tu misión afectó a todo Northland y a cada uno de los aurorianos que viven aquí.",
  ui_story_5061_50611202_22_dialog_content = "Llegar al final nunca fue el propósito de tu misión... El verdadero significado radica en cada momento de paz que llevaste a la gente de este reino.",
  ui_story_5061_50611202_23_dialog_content = "Entonces, gracias... Gracias por todo lo que has hecho por nosotros.",
  ui_story_5061_50611202_24_dialog_content = "...Gracias.",
  ui_story_5061_50611202_25_dialog_content = "... Recuerdo que, una vez... alguien también me encontró así...",
  ui_story_5061_50611202_26_dialog_content = "... Me agradeció por mi esfuerzo e incluso se convirtió en mi compañero.",
  ui_story_5061_50611202_27_dialog_content = "¡Y hay muchas otras personas que también les encantaría ser amigos contigo! Ya no tienes que cargar con esta carga solo.",
  ui_story_5061_50611202_28_dialog_content = "¡Todos aquí están dispuestos a luchar a tu lado!",
  ui_story_5061_50611202_29_dialog_content = "... Pero yo... Después de salir del combate, todos los dispositivos de conexión dejaron de funcionar.",
  ui_story_5061_50611202_30_dialog_content = "... A partir de ahora, no soy más que chatarra de metal sin sentido.",
  ui_story_5061_50611202_31_dialog_content = "... No te sirvo de nada.",
  ui_story_5061_50611202_32_dialog_content = "Eso no es cierto en absoluto. Tu corazón, tus palabras, tu mente... Todas esas cosas nos dan fuerza y ayudan a hacer del mundo un lugar mejor.",
  ui_story_5061_50611202_33_dialog_content = "¿Corazón? ¿Mente? ¿Quieres decir... quieres mi unidad de almacenamiento? ¿Internos o externos?",
  ui_story_5061_50611202_34_dialog_content = "Eh... supongo que realmente no hace una diferencia. ¡Oye, podrías decirme algo? ¿Northland era un lugar cálido en el pasado?",
  ui_story_5061_50611202_35_dialog_content = "Era cálido.",
  ui_story_5061_50611202_36_dialog_content = "¿Por qué, entonces?",
  ui_story_5061_50611202_37_dialog_content = "Debido a las diferentes posiciones del círculo crepuscular, en el pasado de este mundo, no existían cosas como días eternos y noches eternas.",
  ui_story_5061_50611202_38_dialog_content = "Ya veo, así que Antony tenía razón desde el principio. ¡Muchas gracias, No. 33! Acabas de darle al mundo una respuesta muy importante sobre su pasado.",
  ui_story_5061_50611202_39_dialog_content = "Sin embargo, no sé por qué es así y no puedo proporcionarte las respuestas reales.",
  ui_story_5061_50611202_40_dialog_content = "¡Eso también está bien! Descubrir la verdad es de lo que se trata nuestro viaje. Es algo que todo Aurorian vivo sabe, de alguna manera u otra.",
  ui_story_5061_50611202_41_dialog_content = "Comprendo.",
  ui_story_5061_50611202_42_dialog_content = "Oye... ¿Quieres venir con nosotros?",
  ui_story_5061_50611202_43_dialog_content = "¿Yo?",
  ui_story_5061_50611202_44_dialog_content = "¡Claro! Después de todo, tú también eres parte de nuestro mundo. ¿No quieres experimentarlo por ti mismo?",
  ui_story_5061_50611202_45_dialog_content = "¡Vamos! El primer paso siempre es el más difícil, ¡pero estarás bien!",
  ui_story_5061_50611202_46_dialog_content = "... Pero... mis dispositivos de conexión... Ya he perdido la capacidad de recibir señales externas. Yo...",
  ui_story_5061_50611202_47_dialog_content = "Solo toma las cosas paso a paso, y te prometo que no te caerás.",
  ui_story_5061_50611202_48_dialog_content = "¡No me llaman Navegante sin razón, ya sabes! Seré tus ojos, ¡así que solo mantén la cabeza en alto!",
  ui_story_5061_50611202_49_dialog_content = "Esto es-!",
  ui_story_5061_50611202_50_dialog_content = "Un transmisor improvisado y desordenado... configurado para coincidir específicamente con mi canal...",
  ui_story_5061_50611202_51_dialog_content = "¿Listo? Tres, dos, uno...",
  ui_story_5061_50611202_52_dialog_content = "¡Bienvenidos al mundo exterior!",
  ui_story_5061_50611202_53_dialog_content = "Lo siento, no tuvimos la oportunidad de presentarnos adecuadamente antes.",
  ui_story_5061_50611202_54_dialog_content = "Este es el Maestro Novio, un espíritu de montaña de Northland. Su escudo protegió a nuestra Lumina de ser absorbida hace un momento.",
  ui_story_5061_50611202_55_dialog_content = "Así fue como PlayerName logró usar sus poderes en No. 33 sin ser contraatacado.",
  ui_story_5061_50611202_56_dialog_content = "Un placer conocerte, Señorita Zarya.",
  ui_story_5061_50611202_57_dialog_content = "Por el bien de Northland y el futuro de todos los aurorianos, debo pedir que mantengamos este incidente en secreto.",
  ui_story_5061_50611202_58_dialog_content = "Aunque los eventos de hoy fueron increíblemente significativos, no podemos permitir que las otras fuerzas se enteren de lo que ha ocurrido aquí. Dada la situación actual, no tenemos más opción que permitir cierto grado de investigación externa en este lugar.",
  ui_story_5061_50611202_59_dialog_content = "Sin embargo, te ruego humildemente que mantengas en secreto la conexión entre estas ruinas y la Chispa.",
  ui_story_5061_50611202_60_dialog_content = "Aunque la plaga de Eclipsites es un problema constante para Su Majestad... Está lejos de ser su preocupación más urgente.",
  ui_story_5061_50611202_61_dialog_content = "Aurorianos y su destructiva búsqueda de un poder cada vez mayor... Esto es lo que más preocupa a Queen Bethlehem.",
  ui_story_5061_50611202_62_dialog_content = "... Entendido. El mundo todavía no está preparado para un descubrimiento como este.",
  ui_story_5061_50611202_63_dialog_content = "... Muy bien, Maestro Novio.",
  ui_story_5061_50611202_64_dialog_content = "Gracias a todos por su cooperación. Si me disculpan, debo irme ahora...",
  ui_story_5061_50611202_65_dialog_content = "<size=45>¡Espera!</size>",
  ui_story_5061_50611202_66_dialog_content = "¿Mmm? ¿Pasa algo, señorita Zarya?",
  ui_story_5061_50611202_67_dialog_content = "Lo-lo siento, no quise gritar así...",
  ui_story_5061_50611202_68_dialog_content = "Yo... solo quería saber... Qué pasó con mi hermana al final...",
  ui_story_5061_50611202_69_dialog_content = "Su nombre era Alina. Hace cien años, ella...",
  ui_story_5061_50611202_70_dialog_content = "... era el capitán de los Patrulleros de Primavera, quienes estuvieron presentes durante el incidente de la Aurorastorm. ¿Es correcto?",
  ui_story_5061_50611202_71_dialog_content = "¡¿T-Todavía recuerdas?!",
  ui_story_5061_50611202_72_dialog_content = "Tu conocimiento parece estar un poco desactualizado, señorita Zarya.",
  ui_story_5061_50611202_73_dialog_content = "¿Ah?",
  ui_story_5061_50611202_74_dialog_content = "Ahora, por favor déjenme... No, permítanme transmitirles el \"final\" de la señorita Alina.",
  ui_story_5061_50611202_75_dialog_content = "... ¡Tú!",
  ui_story_5061_50611202_76_dialog_content = "No hay necesidad de preocuparse. PlayerName ya me ha ayudado a reiniciar mi Plantilla de Eco para recuperar mis recuerdos. Pero él no ha despertado del enorme agotamiento.",
  ui_story_5061_50611202_77_dialog_content = "El yo actual ya no se involucrará en acciones incontrolables.",
  ui_story_5061_50611202_78_dialog_content = "... O-Okay, por favor dime qué le pasó a mi hermana.",
  ui_story_5061_50611202_79_dialog_content = "Ese día, justo cuando la señorita Alina decidió sacrificarse...",
  ui_story_5061_50611202_80_dialog_content = "Alina! ¿Estás ahí afuera?!",
  ui_story_5061_50611202_81_dialog_content = "¡Eso suena como Zarya! ¡Pero cómo me encontró aquí?!",
  ui_story_5061_50611202_82_dialog_content = "¡Hay una desviación en la calibración automática del concentrador!",
  ui_story_5061_50611202_83_dialog_content = "¡Se siente atraído por un barco en espera más poderoso!",
  ui_story_5061_50611202_84_dialog_content = "(Si elijo a alguien con mayor talento y tasas de supervivencia para completar el protocolo... ¡todos podrán sobrevivir!)",
  ui_story_5061_50611202_85_dialog_content = "¡Cálculo completado! ¡Ejecuta el plan óptimo!",
  ui_story_5061_50611202_86_dialog_content = "¡¿Qué hago ahora?!",
  ui_story_5061_50611202_87_dialog_content = "¡Corre! ¡Cuanto más lejos, mejor! ¡Este lugar está a punto de ser completamente destruido!",
  ui_story_5061_50611202_88_dialog_content = "Pero, ¿qué les pasará a ti y a Zarya?!",
  ui_story_5061_50611202_89_dialog_content = "—La señorita Zarya quiere que sobrevivas, y yo también.",
  ui_story_5061_50611202_90_dialog_content = "Entonces, de un solo golpe, desataste todo tu poder, aniquilando a todos los Eclipsites presentes.",
  ui_story_5061_50611202_91_dialog_content = "Como efecto secundario de la energía, te selló a ti y a las ruinas enteras en hielo.",
  ui_story_5061_50611202_92_dialog_content = "La razón por la que pudiste acceder a mis recuerdos a través de la Lumina de las ruinas es porque las ruinas ya te reconocen como parte de ellas.",
  ui_story_5061_50611202_93_dialog_content = "¿Eso significa que mi hermana... logró escapar?",
  ui_story_5061_50611202_94_dialog_content = "Sí. Poco después, Lady Alina regresó a la seguridad de Northland junto con sus compañeros heridos.",
  ui_story_5061_50611202_95_dialog_content = "Fue entonces cuando ella informó de la existencia de No. 33... O mejor dicho, el Espíritu de la Aurora.",
  ui_story_5061_50611202_96_dialog_content = "... ¡Así que sobrevivió, después de todo! ¡Mi hermana salió viva!",
  ui_story_5061_50611202_97_dialog_content = "Espera... Si yo me convertí en el nuevo recipiente y Alina sobrevivió gracias a eso...",
  ui_story_5061_50611202_98_dialog_content = "¿Eso significa... que la protegí?",
  ui_story_5061_50611202_99_dialog_content = "Parece que sí. Lady Alina estaba devastada por la pérdida de su hermana menor y, al igual que tú, vino a este mismo lugar para buscarte.",
  ui_story_5061_50611202_100_dialog_content = "Desafortunadamente, el hielo que cubría la montaña era aún más denso en ese momento, y el estado inactivo de No. 33 le impedía enviar o recibir señales. Como resultado, nuestros esfuerzos de búsqueda fueron en vano.",
  ui_story_5061_50611202_101_dialog_content = "Alina... Lo siento mucho. No puedo imaginar cuánto debes haber sufrido...",
  ui_story_5061_50611202_102_dialog_content = "Sin embargo, Lady Alina pronto encontró la fuerza para retomar sus deberes.",
  ui_story_5061_50611202_103_dialog_content = "!",
  ui_story_5061_50611202_104_dialog_content = "Cuando dije que tus conocimientos estaban un poco desactualizados, no fue solo porque tu hermana logró sobrevivir...",
  ui_story_5061_50611202_105_dialog_content = "Pero debido a que Lady Alina se convirtió en una <color=#FFB400>Guardiana de la Corte de Northland</color>. Sirvió fiel y admirablemente durante muchos años y falleció en paz a la venerable edad de ochenta y tres años.",
  ui_story_5061_50611202_106_dialog_content = "Un guardián de la corte real... ¡Ese era su sueño!",
  ui_story_5061_50611202_107_dialog_content = "*Sollozando* Estoy... Estoy tan feliz... ¡Mi hermana pudo cumplir su sueño!",
  ui_story_5061_50611202_108_dialog_content = "El día de su promoción, Lady Alina tuvo estas palabras para decir:",
  ui_story_5061_50611202_109_dialog_content = "¡Uf! Parece que finalmente soy tan fuerte como Zarya siempre pensó que era.",
  ui_story_5061_50611202_110_dialog_content = "No te preocupes, Alina... ¡Me aseguraré de vivir bien por los dos!",
  ui_story_5061_50611202_111_dialog_content = "Te protegí... ¿Eso también me hace fuerte? Boo-hoo...",
  ui_story_5061_50611202_112_dialog_content = "Yo... prometo vivir bien por los dos también...",
  ui_story_5061_50611202_113_dialog_content = "Gracias, Alina... Mi dulce, dulce hermana...",
  ui_story_5061_50611202_114_dialog_content = "<size=45>...¡Waaaaaaah!</size>",
  ui_story_5061_50611202_115_dialog_content = "(Uf... Mi cabeza da vueltas...)",
  ui_story_5061_50611202_116_dialog_content = "(¿Alguien... está llorando?)",
  ui_story_5061_50611202_117_dialog_content = "Zarya... ¿estabas llorando hace un momento?",
  ui_story_5061_50611202_118_dialog_content = "¡...!",
  ui_story_5061_50611202_119_dialog_content = "¡O-Claro que no!",
  ui_story_5061_50611202_120_dialog_content = "Pero tus ojos están todos rojos e hinchados...",
  ui_story_5061_50611202_121_dialog_content = "¡Es solo nieve! ¡Tengo nieve en mis ojos!",
  ui_story_5061_50611202_122_dialog_content = "Pfffff—",
  ui_story_5061_50611202_123_dialog_content = "¿Y de qué te ríes, Sr. Antony?!",
  ui_story_5061_50611202_124_dialog_content = "¡Oh, nada! De todos modos, Maestro Novio, muchas gracias por—",
  ui_story_5061_50611202_125_dialog_content = "¿Eh? ¿Adónde fue él?",
  ui_story_5061_50611202_126_dialog_content = "Estaba aquí hace un segundo...",
  ui_story_5061_50611301_1_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_5061_50611301_2_dialog_content = "Muy bien, esa debería ser la última tanda de piezas.",
  ui_story_5061_50611301_3_dialog_content = "Reunir todos estos componentes fue todo un desafío. ¡Recorrimos cada centímetro de la montaña solo para conseguir estos!",
  ui_story_5061_50611301_4_dialog_content = "Afortunadamente, el Maestro Novio ha estado vigilando de cerca las ruinas que salpican el paisaje de nuestro reino. De lo contrario, nunca habríamos recolectado tantas piezas utilizables.",
  ui_story_5061_50611301_5_dialog_content = "A pesar de nuestros mejores esfuerzos, aún no podemos reparar esta instalación. Lo siento.",
  ui_story_5061_50611301_6_dialog_content = "¿Por qué te disculpas, No. 33? No estamos intentando reparar las ruinas, ¿recuerdas? Solo queremos apagar el concentrador de Lumina.",
  ui_story_5061_50611301_7_dialog_content = "Después de una evaluación detallada del daño del concentrador, el Palacio de Invierno lo ha considerado demasiado peligroso para seguir utilizándolo. La decisión más sensata en este momento es apagarlo.",
  ui_story_5061_50611301_8_dialog_content = "El Maestro Novio está ajustando los suministros de energía de las ruinas cercanas para compensar la falta de cobertura de la barrera. La Lumina de estas ruinas también será redirigida.",
  ui_story_5061_50611301_9_dialog_content = "Al menos, eso es más o menos cómo entendí su plan. El resto, sin embargo, está más allá de mi comprensión...",
  ui_story_5061_50611301_10_dialog_content = "En cualquier caso, la anomalía de Lumina debería resolverse pronto.",
  ui_story_5061_50611301_11_dialog_content = "Una vez desactivado el concentrador, la Corte puede programar las reparaciones en una fecha posterior.",
  ui_story_5061_50611301_12_dialog_content = "¿Entonces crees que podremos desactivar el concentrador usando estas piezas?",
  ui_story_5061_50611301_13_dialog_content = "Sí, un apagado directo podría provocar un colapso o una explosión. Tendremos que esperar hasta que se repare el módulo central antes de apagarlo.",
  ui_story_5061_50611301_14_dialog_content = "Durante el apagado, la Lumina acumulada a largo plazo dentro del concentrador será eliminada.",
  ui_story_5061_50611301_15_dialog_content = "Esto podría provocar terremotos menores y fenómenos de auroras. Por favor, prepárate para el posible impacto.",
  ui_story_5061_50611301_16_dialog_content = "Muy bien, iniciaré el proceso de apagado ahora.",
  ui_story_5061_50611301_17_dialog_content = "Una vez desactivado, ya no necesitarás estar conectado a él, ¿verdad?",
  ui_story_5061_50611301_18_dialog_content = "Sí. No necesitaré una conexión, al menos hasta que comiencen los trabajos de reparación.",
  ui_story_5061_50611301_19_dialog_content = "Entonces... ¿Quieres venir a echar un vistazo a mi Coloso?",
  ui_story_5061_50611301_20_dialog_content = "Dijiste que querías ver cómo viven otros Aurorianos en el mundo, ¿no es cierto?",
  ui_story_5061_50611301_21_dialog_content = "?",
  ui_story_5061_50611301_22_dialog_content = "Yo...",
  ui_story_5061_50611301_23_dialog_content = "He experimentado una emoción que rara vez se ha registrado antes. ¿Podría ser... vacilación?",
  ui_story_5061_50611301_24_dialog_content = "Quizás la emoción simplemente te está afectando la cabeza? Hmm, me pregunto cómo describirías eso...",
  ui_story_5061_50611301_25_dialog_content = "¡Lo tengo! ¡Tu dispositivo de almacenamiento está siendo sobrecargado temporalmente!",
  ui_story_5061_50611301_26_dialog_content = "¡Mira, está empezando!",
  ui_story_5061_50611301_27_dialog_content = "<color=#e8d9bb>Rumble-Rumble-Rumble-</color>",
  ui_story_5061_50611301_28_dialog_content = "<color=#e8d9bb>El Lumina, que estuvo obstruido durante mucho tiempo, finalmente se libera ahora, volviendo al ciclo de energía de Astra.</color>",
  ui_story_5061_50611301_29_dialog_content = "<color=#e8d9bb>Una vez más, la deslumbrante aurora aparece en los cielos en la frontera.</color>",
  ui_story_5061_50611301_30_dialog_content = "Realmente tienes que verlo para creerlo...",
  ui_story_5061_50611301_31_dialog_content = "Esta aurora es como algo sacado de un cuento de hadas. No tenía idea de que algo así pudiera ser creado por una máquina.",
  ui_story_5061_50611301_32_dialog_content = "En el continente de Astra, hay muchas instalaciones energéticas como esta.",
  ui_story_5061_50611301_33_dialog_content = "Su poder se conecta directamente con el núcleo de la Tierra, simbolizando la increíble fuerza de las civilizaciones antiguas para remodelar el mundo.",
  ui_story_5061_50611301_34_dialog_content = "Pero una aurora como esta solo se puede ver aquí, ¿verdad?",
  ui_story_5061_50611301_35_dialog_content = "Así es. Solo es visible aquí debido a nuestra posición cerca del círculo del crepúsculo, donde la luz y la oscuridad se encuentran.",
  ui_story_5061_50611301_36_dialog_content = "Los cielos son extremadamente claros en esta área, ¡y la colisión de partículas de Lumina es muy notable aquí!",
  ui_story_5061_50611301_37_dialog_content = "He soñado con este momento más veces de las que puedo contar... Pero nada se compara con verlo con mis propios ojos.",
  ui_story_5061_50611301_38_dialog_content = "Antony...",
  ui_story_5061_50611301_39_dialog_content = "(Debe haber tantas otras personas como él en el mundo: personas que exploran lo desconocido con solo su intuición y conocimientos autodidactas para guiarlos...)",
  ui_story_5061_50611301_40_dialog_content = "(Me hace feliz saber que personas como él pueden descubrir los secretos del mundo y realizar sus sueños también.)",
  ui_story_5061_50611301_41_dialog_content = "Finalmente entiendo por qué estás constantemente buscando respuestas a las preguntas más difíciles de la vida, Antony.",
  ui_story_5061_50611301_42_dialog_content = "La forma en que mi corazón está latiendo rápido ahora mismo...",
  ui_story_5061_50611301_43_dialog_content = "Me hace querer explorar preguntas aún más profundas sobre nuestro mundo.",
  ui_story_5061_50611301_44_dialog_content = "... Por ejemplo: ¿En qué tipo de mundo vivimos realmente?",
  ui_story_5061_50611301_45_dialog_content = "... ¿De dónde venimos?",
  ui_story_5061_50611301_46_dialog_content = "... ¿Hacia dónde se dirigen?"
}
return config
